/* DAWAH X — ahmad, অধ্যায় 92 · খণ্ড 92 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][92]=[[18201,18201,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَقِيلٍ هَاشِمِ بْنِ بِلَالٍ ‏ ‏عَنْ ‏ ‏سَابِقِ بْنِ نَاجِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏الْحَبَشِيُّ ‏ ‏قَالَ ‏ ‏مَرَّ بِهِ رَجُلٌ فِي مَسْجِدِ ‏ ‏حِمْصَ ‏ ‏فَقِيلَ هَذَا ‏ ‏خَدَمَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ إِلَيْهِ فَقَالَ حَدِّثْنِي حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَتَدَاوَلْهُ بَيْنَكَ وَبَيْنَهُ الرِّجَالُ قَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ يَقُولُ حِينَ يُمْسِي وَحِينَ يُصْبِحُ رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيًّا ثَلَاثَ مَرَّاتٍ إِلَّا كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُرْضِيَهُ ‏","","",""],[18202,18202,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏رَجُلٌ خَدَمَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِ سِنِينَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قُرِّبَ لَهُ طَعَامٌ قَالَ بِسْمِ اللَّهِ فَإِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ ‏ ‏اللَّهُمَّ أَطْعَمْتَ وَأَسْقَيْتَ وَأَغْنَيْتَ وَأَقْنَيْتَ وَهَدَيْتَ ‏ ‏وَاجْتَبَيْتَ ‏ ‏فَلَكَ الْحَمْدُ عَلَى مَا أَعْطَيْتَ ‏","","",""],[18203,18203,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَدْرَعِ ‏ ‏قَالَ ‏ ‏كُنْتُ أَحْرُسُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَخَرَجَ لِبَعْضِ حَاجَتِهِ قَالَ فَرَآنِي فَأَخَذَ بِيَدِي فَانْطَلَقْنَا فَمَرَرْنَا عَلَى رَجُلٍ ‏ ‏يُصَلِّي يَجْهَرُ بِالْقُرْآنِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَسَى أَنْ يَكُونَ ‏ ‏مُرَائِيًا ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏يُصَلِّي يَجْهَرُ بِالْقُرْآنِ قَالَ فَرَفَضَ يَدِي ثُمَّ قَالَ إِنَّكُمْ لَنْ تَنَالُوا هَذَا الْأَمْرَ ‏ ‏بِالْمُغَالَبَةِ ‏ ‏قَالَ ثُمَّ خَرَجَ ذَاتَ لَيْلَةٍ وَأَنَا أَحْرُسُهُ لِبَعْضِ حَاجَتِهِ فَأَخَذَ بِيَدِي فَمَرَرْنَا عَلَى رَجُلٍ ‏ ‏يُصَلِّي بِالْقُرْآنِ قَالَ فَقُلْتُ عَسَى أَنْ يَكُونَ ‏ ‏مُرَائِيًا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلَّا إِنَّهُ ‏ ‏أَوَّابٌ ‏ ‏قَالَ فَنَظَرْتُ فَإِذَا هُوَ ‏ ‏عَبْدُ اللَّهِ ذُو الْبِجَادَيْنِ ‏","","",""],[18204,18204,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُقَاتِلُونَ ‏ ‏جَزِيرَةَ الْعَرَبِ ‏ ‏فَيَفْتَحُهَا اللَّهُ وَتُقَاتِلُونَ ‏ ‏فَارِسَ ‏ ‏فَيَفْتَحُهُمْ اللَّهُ وَتُقَاتِلُونَ ‏ ‏الرُّومَ ‏ ‏فَيَفْتَحُهُمْ اللَّهُ وَتُقَاتِلُونَ ‏ ‏الدَّجَّالَ ‏ ‏فَيَفْتَحُهُ اللَّهُ ‏","","",""],[18205,18205,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الْفَزَارِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ فَأَتَاهُ قَوْمٌ مِنْ قِبَلِ الْمَغْرِبِ عَلَيْهِمْ ثِيَابُ ‏ ‏الصُّوفِ ‏ ‏فَوَافَقُوهُ عِنْدَ ‏ ‏أَكَمَةٍ ‏ ‏وَهُمْ قِيَامٌ وَهُوَ قَاعِدٌ فَأَتَيْتُهُ فَقُمْتُ بَيْنَهُمْ وَبَيْنَهُ فَحَفِظْتُ مِنْهُ أَرْبَعَ كَلِمَاتٍ أَعُدُّهُنَّ فِي يَدِي قَالَ ‏ ‏تَغْزُونَ ‏ ‏جَزِيرَةَ الْعَرَبِ ‏ ‏فَيَفْتَحُهَا اللَّهُ ثُمَّ تَغْزُونَ ‏ ‏فَارِسَ ‏ ‏فَيَفْتَحُهَا اللَّهُ ثُمَّ تَغْزُونَ ‏ ‏الرُّومَ ‏ ‏فَيَفْتَحُهَا اللَّهُ ثُمَّ تَغْزُونَ ‏ ‏الدَّجَّالَ ‏ ‏فَيَفْتَحُهُ اللَّهُ قَالَ ‏ ‏نَافِعٌ ‏ ‏يَا ‏ ‏جَابِرُ ‏ ‏أَلَا ‏ ‏تَرَى أَنَّ ‏ ‏الدَّجَّالَ ‏ ‏لَا يَخْرُجُ حَتَّى تُفْتَحَ ‏ ‏الرُّومُ ‏","","",""],[18206,18206,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏حَدَّثَنِي ‏ ‏حَنْظَلَةُ بْنُ عَلِيٍّ ‏ ‏أَنَّ ‏ ‏مِحْجَنَ بْنَ الْأَدْرَعِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ فَإِذَا هُوَ بِرَجُلٍ قَدْ قَضَى صَلَاتَهُ وَهُوَ يَتَشَهَّدُ وَهُوَ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ بِاللَّهِ الْوَاحِدِ الْأَحَدِ ‏ ‏الصَّمَدِ ‏ ‏الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ قَالَ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ غُفِرَ لَهُ قَدْ غُفِرَ لَهُ قَدْ غُفِرَ لَهُ ثَلَاثَ مَرَّاتٍ ‏","","",""],[18207,18207,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏مِحْجَنِ بْنِ الْأَدْرَعِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ فَقَالَ ‏ ‏يَوْمُ الْخَلَاصِ وَمَا يَوْمُ الْخَلَاصِ يَوْمُ الْخَلَاصِ وَمَا يَوْمُ الْخَلَاصِ يَوْمُ الْخَلَاصِ وَمَا يَوْمُ الْخَلَاصِ ثَلَاثًا فَقِيلَ لَهُ وَمَا يَوْمُ الْخَلَاصِ قَالَ يَجِيءُ ‏ ‏الدَّجَّالُ ‏ ‏فَيَصْعَدُ ‏ ‏أُحُدًا ‏ ‏فَيَنْظُرُ ‏ ‏الْمَدِينَةَ ‏ ‏فَيَقُولُ لِأَصْحَابِهِ أَتَرَوْنَ هَذَا الْقَصْرَ الْأَبْيَضَ هَذَا ‏ ‏مَسْجِدُ أَحْمَدَ ‏ ‏ثُمَّ يَأْتِي ‏ ‏الْمَدِينَةَ ‏ ‏فَيَجِدُ بِكُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْهَا مَلَكًا مُصْلِتًا فَيَأْتِي ‏ ‏سَبْخَةَ ‏ ‏الْحَرْفِ ‏ ‏فَيَضْرِبُ ‏ ‏رُوَاقَهُ ‏ ‏ثُمَّ تَرْجُفُ ‏ ‏الْمَدِينَةُ ‏ ‏ثَلَاثَ رَجَفَاتٍ فَلَا ‏ ‏يَبْقَى مُنَافِقٌ وَلَا مُنَافِقَةٌ وَلَا فَاسِقٌ وَلَا فَاسِقَةٌ إِلَّا خَرَجَ إِلَيْهِ فَذَلِكَ يَوْمُ الْخَلَاصِ ‏","","",""],[18208,18208,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ أَبِي رَجَاءٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏بُرَيْدَةُ ‏ ‏عَلَى بَابِ الْمَسْجِدِ فَمَرَّ ‏ ‏مِحْجَنٌ ‏ ‏عَلَيْهِ ‏ ‏وَسُكْبَةُ ‏ ‏يُصَلِّي فَقَالَ ‏ ‏بُرَيْدَةُ ‏ ‏وَكَانَ فِيهِ ‏ ‏مُرَاحٌ ‏ ‏لِمِحْجَنٍ ‏ ‏أَلَا تُصَلِّي كَمَا ‏ ‏يُصَلِّي هَذَا فَقَالَ ‏ ‏مِحْجَنٌ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ بِيَدِي فَصَعِدَ عَلَى ‏ ‏أُحُدٍ ‏ ‏فَأَشْرَفَ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏وَيْلُ أُمِّهَا قَرْيَةً يَدَعُهَا أَهْلُهَا خَيْرَ مَا تَكُونُ ‏ ‏أَوْ كَأَخْيَرِ مَا تَكُونُ ‏ ‏فَيَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِهَا مَلَكًا مُصْلِتًا جَنَاحَيْهِ فَلَا يَدْخُلُهَا قَالَ ثُمَّ نَزَلَ وَهُوَ آخِذٌ بِيَدِي فَدَخَلَ الْمَسْجِدَ وَإِذَا هُوَ بِرَجُلٍ ‏ ‏يُصَلِّي فَقَالَ لِي مَنْ هَذَا فَأَتَيْتُ عَلَيْهِ فَأَثْنَيْتُ عَلَيْهِ خَيْرًا فَقَالَ اسْكُتْ لَا تُسْمِعْهُ فَتُهْلِكَهُ قَالَ ثُمَّ أَتَى حُجْرَةَ امْرَأَةٍ مِنْ نِسَائِهِ فَنَفَضَ يَدَهُ مِنْ يَدِي قَالَ إِنَّ خَيْرَ دِينِكُمْ أَيْسَرُهُ إِنَّ خَيْرَ دِينِكُمْ أَيْسُرُهُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجَاءِ بْنِ أَبِي رَجَاءٍ الْبَاهِلِيِّ ‏ ‏عَنْ ‏ ‏مِحْجَنٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَذَكَرَ مَعْنَاهُ وَلَمْ يَقُلْ ‏ ‏حَجَّاجٌ ‏ ‏وَلَا ‏ ‏أَبُو النَّضْرِ ‏ ‏بِجَنَاحِهِ ‏","","",""],[18209,18209,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏بُسْرٍ ‏ ‏أَوْ ‏ ‏بُسْرِ بْنِ مِحْجَنٍ ‏ ‏ثُمَّ كَانَ يَقُولُ بَعْدُ ‏ ‏عَنْ ‏ ‏أَبِي مِحْجَنٍ الدِّيلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ فَحَضَرَتْ الصَّلَاةُ فَصَلَّى فَقَالَ لِي أَلَا صَلَّيْتَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ قَدْ صَلَّيْتُ فِي الرَّحْلِ ثُمَّ أَتَيْتُكَ قَالَ ‏ ‏فَإِذَا فَعَلْتَ فَصَلِّ مَعَهُمْ وَاجْعَلْهَا ‏ ‏نَافِلَةً ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَلَمْ يَقُلْ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَلَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَاجْعَلْهَا ‏ ‏نَافِلَةً ‏","","",""],[18210,18210,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ ثَعْلَبَةَ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏حُلَّتَانِ ‏ ‏مِنْ ‏ ‏حُلَلِ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ يَا ‏ ‏ضَمْرَةُ ‏ ‏أَتَرَى ثَوْبَيْكَ هَذَيْنِ مُدْخِلَيْكَ الْجَنَّةَ فَقَالَ لَئِنْ اسْتَغْفَرْتَ لِي يَا رَسُولَ اللَّهِ لَا أَقْعُدُ حَتَّى أَنْزَعَهُمَا عَنِّي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اغْفِرْ ‏ ‏لِضَمْرَةَ بْنِ ثَعْلَبَةَ ‏ ‏فَانْطَلَقَ سَرِيعًا حَتَّى نَزَعَهُمَا عَنْهُ ‏","","",""],[18211,18211,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي أَهْلِي ‏ ‏بِلَقُوحٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنِي أَنْ أَحْلُبَهَا فَحَلَبْتُهَا فَقَالَ لِي ‏ ‏دَعْ ‏ ‏دَاعِيَ ‏ ‏اللَّبَنِ ‏","","",""],[18212,18212,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏رَجُلٍ مِنْ الْحَيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ضِرَارَ بْنَ الْأَزْوَرِ ‏ ‏قَالَ ‏ ‏أَهْدَيْنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقْحَةً ‏ ‏قَالَ فَحَلَبْتُهَا قَالَ فَلَمَّا أَخَذْتُ ‏ ‏لِأُجْهِدَهَا ‏ ‏قَالَ ‏ ‏لَا تَفْعَلْ دَعْ دَاعِيَ اللَّبَنِ ‏","","",""],[18213,18213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سِنَانٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِهِ وَهُوَ يَحْلُبُ فَقَالَ ‏ ‏دَعْ ‏ ‏دَاعِيَ ‏ ‏اللَّبَنِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ بَكَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏أَوْ عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ بَحِيرٍ ‏ ‏عَنْ ‏ ‏ضِرَارِ بْنِ الْأَزْوَرِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏","","",""],[18214,18214,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ الْجُشَمِيُّ ‏ ‏عَنْ ‏ ‏شَيْخٍ لَهُمْ يُقَالُ لَهُ ‏ ‏جَعْدَةُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى لِرَجُلٍ رُؤْيَا قَالَ فَبَعَثَ إِلَيْهِ فَجَاءَ فَجَعَلَ يَقُصُّهَا عَلَيْهِ وَكَانَ الرَّجُلُ عَظِيمَ الْبَطْنِ قَالَ فَجَعَلَ يَقُولُ بِأُصْبُعِهِ فِي بَطْنِهِ لَوْ كَانَ هَذَا فِي غَيْرِ هَذَا لَكَانَ خَيْرًا لَكَ ‏","","",""],[18215,18215,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْحَضْرَمِيِّ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَمْكُثُ الْمُهَاجِرُ ‏ ‏بِمَكَّةَ ‏ ‏بَعْدَ قَضَاءِ ‏ ‏نُسُكِهِ ‏ ‏ثَلَاثًا ‏ ‏قَالَ ‏ ‏مَا كَانَ أَشَدَّ عَلَى ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏أَنْ يَقُولَ حَدَّثَنَا ‏","","",""],[18216,18216,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ الْعَلَاءِ بْنِ الْحَضْرَمِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا بِهِ ‏ ‏هُشَيْمٌ ‏ ‏مَرَّتَيْنِ مَرَّةً عَنْ ‏ ‏ابْنِ الْعَلَاءِ ‏ ‏وَمَرَّةً لَمْ يَصِلْ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏كَتَبَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَدَأَ بِنَفْسِهِ ‏","","",""],[18217,18217,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏","","",""],[18218,18218,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏","","",""],[18219,18219,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏إِنَّمَا هُنَّ أَرْبَعٌ لَا تُشْرِكُوا بِاللَّهِ شَيْئًا وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا تَسْرِقُوا وَلَا تَزْنُوا ‏","","",""],[18220,18220,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏أَلَا إِنَّمَا هُنَّ أَرْبَعٌ أَنْ لَا تُشْرِكُوا بِاللَّهِ شَيْئًا وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا تَزْنُوا وَلَا تَسْرِقُوا قَالَ فَمَا أَنَا ‏ ‏بِأَشَحَّ ‏ ‏عَلَيْهِنَّ مِنِّي إِذْ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18221,18221,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَانْتَثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏","","",""],[18222,18222,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَوْلَى الْقَوْمِ مِنْهُمْ وَابْنُ أُخْتِهِمْ مِنْهُمْ وَحَلِيفُهُمْ مِنْهُمْ ‏","","",""],[18223,18223,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيْشًا ‏ ‏فَقَالَ هَلْ فِيكُمْ مِنْ غَيْرِكُمْ قَالُوا لَا إِلَّا ابْنُ أُخْتِنَا وَحَلِيفُنَا وَمَوْلَانَا فَقَالَ ‏ ‏ابْنُ أُخْتِكُمْ مِنْكُمْ وَحَلِيفُكُمْ مِنْكُمْ وَمَوْلَاكُمْ مِنْكُمْ إِنَّ ‏ ‏قُرَيْشًا ‏ ‏أَهْلُ صِدْقٍ وَأَمَانَةٍ فَمَنْ ‏ ‏بَغَى ‏ ‏لَهَا ‏ ‏الْعَوَائِرَ ‏ ‏أَكَبَّهُ ‏ ‏اللَّهُ فِي النَّارِ لِوَجْهِهِ ‏","","",""],[18224,18224,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرٌ يَعْنِي ابْنَ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَلِيفُنَا مِنَّا وَمَوْلَانَا مِنَّا وَابْنُ أُخْتِنَا مِنَّا ‏","","",""],[18225,18225,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَحْيَى بْنِ خَلَّادٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فِي الْمَسْجِدِ فَصَلَّى قَرِيبًا مِنْهُ ثُمَّ انْصَرَفَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعِدْ صَلَاتَكَ فَإِنَّكَ لَمْ تُصَلِّ قَالَ فَرَجَعَ فَصَلَّى كَنَحْوٍ مِمَّا صَلَّى ثُمَّ انْصَرَفَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ أَعِدْ صَلَاتَكَ فَإِنَّكَ لَمْ تُصَلِّ فَقَالَ يَا رَسُولَ اللَّهِ عَلِّمْنِي كَيْفَ أَصْنَعُ قَالَ ‏ ‏إِذَا اسْتَقْبَلْتَ الْقِبْلَةَ فَكَبِّرْ ثُمَّ اقْرَأْ ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏ثُمَّ اقْرَأْ بِمَا شِئْتَ فَإِذَا رَكَعْتَ فَاجْعَلْ ‏ ‏رَاحَتَيْكَ ‏ ‏عَلَى رُكْبَتَيْكَ وَامْدُدْ ظَهْرَكَ وَمَكِّنْ لِرُكُوعِكَ فَإِذَا رَفَعْتَ رَأْسَكَ فَأَقِمْ صُلْبَكَ حَتَّى تَرْجِعَ الْعِظَامُ إِلَى مَفَاصِلِهَا وَإِذَا سَجَدْتَ فَمَكِّنْ لِسُجُودِكَ فَإِذَا رَفَعْتَ رَأْسَكَ فَاجْلِسْ عَلَى فَخِذِكَ الْيُسْرَى ثُمَّ اصْنَعْ ذَلِكَ فِي كُلِّ رَكْعَةٍ وَسَجْدَةٍ ‏","","",""],[18226,18226,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَحْيَى الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نُصَلِّي يَوْمًا وَرَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ مِنْ الرَّكْعَةِ وَقَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ ‏ ‏رَجُلٌ ‏ ‏وَرَاءَهُ رَبَّنَا لَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ الْمُتَكَلِّمُ ‏ ‏آنِفًا ‏ ‏قَالَ الرَّجُلُ أَنَا يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُ بِضْعَةً وَثَلَاثِينَ مَلَكًا ‏ ‏يَبْتَدِرُونَهَا ‏ ‏أَيُّهُمْ يَكْتُبُهَا أَوَّلًا ‏","","",""],[18227,18227,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ يَحْيَى بْنِ خَلَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَكَانَ بَدْرِيًّا ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَدَخَلَ رَجُلٌ فَصَلَّى فِي نَاحِيَةِ الْمَسْجِدِ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْمُقُهُ ‏ ‏ثُمَّ جَاءَ فَسَلَّمَ فَرَدَّ عَلَيْهِ وَقَالَ ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ قَالَ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏فَقَالَ لَهُ فِي الثَّالِثَةِ ‏ ‏أَوْ فِي الرَّابِعَةِ ‏ ‏وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ أَجْهَدْتُ نَفْسِي فَعَلِّمْنِي وَأَرِنِي فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَدْتَ أَنْ تُصَلِّيَ فَتَوَضَّأْ فَأَحْسِنْ وُضُوءَكَ ثُمَّ اسْتَقْبِلْ الْقِبْلَةَ ثُمَّ كَبِّرْ ثُمَّ اقْرَأْ ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ قَائِمًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ قُمْ فَإِذَا أَتْمَمْتَ صَلَاتَكَ عَلَى هَذَا فَقَدْ أَتْمَمْتَهَا وَمَا انْتَقَصْتَ مِنْ هَذَا مِنْ شَيْءٍ فَإِنَّمَا تُنْقِصُهُ مِنْ صَلَاتِكَ ‏","","",""],[18228,18228,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ يَعْنِي ابْنَ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏طَارِقُ بْنُ عَبْدِ الرَّحْمَنِ الْقُرَشِيُّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَافِعُ بْنُ رِفَاعَةَ ‏ ‏إِلَى مَجْلِسِ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ لَقَدْ نَهَانَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيَوْمَ عَنْ شَيْءٍ كَانَ يَرْفُقُ بِنَا فِي مَعَايِشِنَا فَقَالَ ‏ ‏نَهَانَا عَنْ ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ قَالَ مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا أَوْ لِيُزْرِعْهَا أَخَاهُ أَوْ لِيَدَعْهَا وَنَهَانَا عَنْ كَسْبِ ‏ ‏الْحَجَّامِ ‏ ‏وَأَمَرَنَا أَنْ نُطْعِمَهُ ‏ ‏نَوَاضِحَنَا ‏ ‏وَنَهَانَا عَنْ كَسْبِ الْأَمَةِ إِلَّا مَا عَمِلَتْ بِيَدِهَا وَقَالَ هَكَذَا بِأَصَابِعِهِ نَحْوَ الْخَبْزِ وَالْغَزْلِ وَالنَّفْشِ ‏","","",""],[18229,18229,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏عَرْفَجَةَ بْنِ شُرَيْحٍ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَكُونُ بَعْدِي ‏ ‏هَنَاتٌ ‏ ‏وَهَنَاتٌ ‏ ‏وَرَفَعَ يَدَيْهِ فَمَنْ رَأَيْتُمُوهُ يُفَرِّقُ بَيْنَ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏وَهُمْ جَمِيعٌ فَاقْتُلُوهُ كَائِنًا مَنْ كَانَ مِنْ النَّاسِ ‏","","",""],[18230,18230,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَرْفَجَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهُ سَتَكُونُ ‏ ‏هَنَاتٌ ‏ ‏وَهَنَاتٌ ‏ ‏فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ هَذِهِ الْأُمَّةِ وَهِيَ جَمِيعٌ فَاضْرِبُوهُ بِالسَّيْفِ كَائِنًا مَنْ كَانَ ‏","","",""],[18231,18231,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏عَبَّادَ بْنَ تَمِيمٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُوَيْمِرِ بْنِ أَشْقَرَ ‏ ‏أَنَّهُ ذَبَحَ قَبْلَ أَنْ يَغْدُوَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّهُ ذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَمَا فَرَغَ ‏ ‏فَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَعُودَ لِأُضْحِيَّتِهِ ‏","","",""],[18232,18232,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ الْخَطْمِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ السَّائِبِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنَا قُرَيْظَةَ ‏ ‏أَنَّهُمْ ‏ ‏عُرِضُوا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَمَنَ ‏ ‏قُرَيْظَةَ ‏ ‏فَمَنْ كَانَ مِنْهُمْ ‏ ‏مُحْتَلِمًا ‏ ‏أَوْ نَبَتَتْ ‏ ‏عَانَتُهُ ‏ ‏قُتِلَ وَمَنْ لَا تُرِكَ ‏","","",""],[18233,18233,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏الْحُصَيْنِ بْنِ مِحْصَنٍ ‏ ‏أَنَّ عَمَّةً لَهُ أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَفَرَغَتْ مِنْ حَاجَتِهَا فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذَاتُ زَوْجٍ أَنْتِ قَالَتْ نَعَمْ قَالَ كَيْفَ أَنْتِ لَهُ قَالَتْ مَا ‏ ‏آلُوهُ ‏ ‏إِلَّا مَا عَجَزْتُ عَنْهُ قَالَ ‏ ‏فَانْظُرِي أَيْنَ أَنْتِ مِنْهُ فَإِنَّمَا هُوَ جَنَّتُكِ وَنَارُكِ ‏","","",""],[18234,18234,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رَجُلٌ يُقَالُ لَهُ ‏ ‏رَبِيعَةُ بْنُ عَبَّادٍ ‏ ‏مِنْ ‏ ‏بَنِي الدِّيلِ ‏ ‏وَكَانَ جَاهِلِيًّا ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجَاهِلِيَّةِ فِي سُوقِ ‏ ‏ذِي الْمَجَازِ ‏ ‏وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ قُولُوا ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ تُفْلِحُوا وَالنَّاسُ مُجْتَمِعُونَ عَلَيْهِ وَوَرَاءَهُ رَجُلٌ ‏ ‏وَضِيءُ ‏ ‏الْوَجْهِ أَحْوَلُ ذُو ‏ ‏غَدِيرَتَيْنِ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏صَابِئٌ ‏ ‏كَاذِبٌ يَتْبَعُهُ حَيْثُ ذَهَبَ فَسَأَلْتُ عَنْهُ فَذَكَرُوا لِي نَسَبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالُوا لِي هَذَا عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبَّادٍ الدُّؤَلِيِّ ‏ ‏وَكَانَ جَاهِلِيًّا فَأَسْلَمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ قَالَ فَقُلْتُ مَنْ هَذَا قَالَ هَذَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏وَهُوَ يَذْكُرُ النُّبُوَّةَ قُلْتُ مَنْ هَذَا الَّذِي يُكَذِّبُهُ قَالُوا ‏ ‏هَذَا عَمُّهُ ‏ ‏أَبُو لَهَبٍ ‏ ‏قَالَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏فَقُلْتُ ‏ ‏لِرَبِيعَةَ بْنِ عَبَّادٍ ‏ ‏إِنَّكَ يَوْمَئِذٍ كُنْتَ صَغِيرًا قَالَ لَا وَاللَّهِ إِنِّي يَوْمَئِذٍ لَأَعْقِلُ أَنِّي ‏ ‏لَأَزْفِرُ ‏ ‏الْقِرْبَةَ ‏ ‏يَعْنِي أَحْمِلُهَا ‏","","",""],[18235,18235,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ طَرَفَةَ ‏ ‏أَنَّ جَدَّهُ ‏ ‏عَرْفَجَةَ ‏ ‏أُصِيبَ أَنْفُهُ يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏فِي الْجَاهِلِيَّةِ فَاتَّخَذَ أَنْفًا مِنْ وَرِقٍ فَأَنْتَنَ عَلَيْهِ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَّخِذَ أَنْفًا مِنْ ذَهَبٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَقِيلَ ‏ ‏لِأَبِي الْأَشْهَبِ ‏ ‏أَدْرَكْتَ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏جَدَّهُ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[18236,18236,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ يَعْنِي ابْنَ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّا يُوجِبُ الْغُسْلَ وَعَنْ الْمَاءِ يَكُونُ بَعْدَ الْمَاءِ وَعَنْ الصَّلَاةِ فِي بَيْتِي وَعَنْ الصَّلَاةِ فِي الْمَسْجِدِ وَعَنْ مُؤَاكَلَةِ الْحَائِضِ فَقَالَ ‏ ‏إِنَّ اللَّهَ لَا ‏ ‏يَسْتَحْيِي مِنْ الْحَقِّ وَأَمَّا أَنَا فَإِذَا فَعَلْتُ كَذَا وَكَذَا فَذَكَرَ الْغُسْلَ قَالَ أَتَوَضَّأُ وُضُوئِي لِلصَّلَاةِ أَغْسِلُ فَرْجِي ثُمَّ ذَكَرَ الْغُسْلَ وَأَمَّا الْمَاءُ يَكُونُ بَعْدَ ‏ ‏الْمَاءِ ‏ ‏فَذَلِكَ ‏ ‏الْمَذْيُ ‏ ‏وَكُلُّ ‏ ‏فَحْلٍ ‏ ‏يُمْذِي ‏ ‏فَأَغْسِلُ مِنْ ذَلِكَ فَرْجِي وَأَتَوَضَّأُ وَأَمَّا الصَّلَاةُ فِي الْمَسْجِدِ وَالصَّلَاةُ فِي بَيْتِي فَقَدْ ‏ ‏تَرَى مَا أَقْرَبَ بَيْتِي مِنْ الْمَسْجِدِ وَلَأَنْ أُصَلِّيَ فِي بَيْتِي أَحَبُّ إِلَيَّ مِنْ أَنْ أُصَلِّيَ فِي الْمَسْجِدِ إِلَّا أَنْ تَكُونَ صَلَاةً مَكْتُوبَةً وَأَمَّا مُؤَاكَلَةُ الْحَائِضِ فَآكِلْهَا ‏","","",""],[18237,18237,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مُؤَاكَلَةِ الْحَائِضِ فَقَالَ وَاكِلْهَا ‏","","",""],[18238,18238,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ سَوَادَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَسْلَمَ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لِجَعْفَرِ بْنِ أَبِي طَالِبٍ ‏ ‏أَشْبَهْتَ خَلْقِي وَخُلُقِي ‏","","",""],[18239,18239,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ يَعْنِي الْجُرَيْرِيَّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏مَاعِزٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ إِيمَانٌ بِاللَّهِ وَحْدَهُ ثُمَّ الْجِهَادُ ثُمَّ حَجَّةٌ بَرَّةٌ تَفْضُلُ سَائِرَ الْعَمَلِ كَمَا بَيْنَ مَطْلَعِ الشَّمْسِ إِلَى مَغْرِبِهَا ‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏حَيَّانَ بْنِ عُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَاعِزٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ أَيُّ الْأَعْمَالِ أَفْضَلُ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[18240,18240,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ رَاشِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ثَنَا ‏ ‏أَحْمَرُ بْنُ جَزِيٍّ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ كُنَّا ‏ ‏لَنَأْوِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا ‏ ‏يُجَافِي ‏ ‏مِرْفَقَيْهِ عَنْ جَنْبَيْهِ إِذَا سَجَدَ ‏","","",""],[18241,18241,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عِتْبَانَ ‏ ‏أَوْ ‏ ‏ابْنِ عُتْبَانَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ أَيْ نَبِيَّ اللَّهِ ‏ ‏إِنِّي كُنْتُ مَعَ أَهْلِي فَلَمَّا سَمِعْتُ صَوْتَكَ أَقْلَعْتُ فَاغْتَسَلْتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَاءُ مِنْ الْمَاءِ ‏","","",""],[18242,18242,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏حَكِيمِ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ سَنَّةَ صَاحِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الطَّاعِمُ الشَّاكِرُ لَهُ مِثْلُ أَجْرِ الصَّائِمِ الصَّابِرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَاه ‏ ‏أَحْمَدُ بْنُ حَاتِمٍ الطَّوِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ الدَّرَاوَرْدِيُّ ‏ ‏مِثْلَهُ ‏","","",""],[18243,18243,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ هِنْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏حَرْمَلَةَ بْنَ عَمْرٍو وَهُوَ أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏حَجَجْتُ حَجَّةَ الْوَدَاعِ ‏ ‏مُرْدِفِي ‏ ‏عَمِّي ‏ ‏سِنَانُ بْنُ سَنَّةَ ‏ ‏قَالَ فَلَمَّا وَقَفْنَا ‏ ‏بِعَرَفَاتٍ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا إِحْدَى أُصْبُعَيْهِ عَلَى الْأُخْرَى فَقُلْتُ لِعَمِّي مَاذَا يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ ‏ ‏ارْمُوا الْجَمْرَةَ بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏","","",""],[18244,18244,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏شَبْلَ بْنَ حَامِدٍ الْمُزَنِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ الْأَوْسِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلْوَلِيدَةِ ‏ ‏إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَبِيعُوهَا وَلَوْ ‏ ‏بِضَفِيرٍ ‏ ‏وَالضَّفِيرُ ‏ ‏الْحَبْلُ فِي الثَّالِثَةِ ‏ ‏أَوْ فِي الرَّابِعَةِ ‏","","",""],[18245,18245,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏شِبْلَ بْنَ خُلَيْدٍ الْمُزَنِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ الْأَوْسِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلْوَلِيدَةِ ‏ ‏إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَبِيعُوهَا وَلَوْ بِضَفِيرٍ وَالضَّفِيرُ الْحَبْلُ ‏","","",""],[18246,18246,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مَالِكٍ ابْنِ بَرْصَاءَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُغْزَى ‏ ‏مَكَّةُ ‏ ‏بَعْدَهَا أَبَدًا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْحَارِثُ خُزَاعِيٌّ ‏","","",""],[18247,18247,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مَالِكٍ ابْنِ بَرْصَاءَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏لَا ‏ ‏تُغْزَى هَذِهِ بَعْدَهَا أَبَدًا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[18248,18248,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الطَّائِفِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَوْسِ بْنِ حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي الْوَفْدِ الَّذِينَ أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُوا مِنْ ‏ ‏ثَقِيفٍ ‏ ‏مِنْ ‏ ‏بَنِي مَالِكٍ ‏ ‏أَنْزَلَنَا فِي ‏ ‏قُبَّةٍ ‏ ‏لَهُ فَكَانَ يَخْتَلِفُ إِلَيْنَا بَيْنَ بُيُوتِهِ وَبَيْنَ الْمَسْجِدِ فَإِذَا صَلَّى الْعِشَاءَ الْآخِرَةَ انْصَرَفَ إِلَيْنَا فَلَا ‏ ‏يَبْرَحُ ‏ ‏يُحَدِّثُنَا ‏ ‏وَيَشْتَكِي ‏ ‏قُرَيْشًا ‏ ‏وَيَشْتَكِي أَهْلَ ‏ ‏مَكَّةَ ‏ ‏ثُمَّ يَقُولُ لَا سَوَاءَ كُنَّا ‏ ‏بِمَكَّةَ ‏ ‏مُسْتَذَلِّينَ ‏ ‏أَوْ مُسْتَضْعَفِينَ ‏ ‏فَلَمَّا خَرَجْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَانَتْ ‏ ‏سِجَالُ ‏ ‏الْحَرْبِ عَلَيْنَا وَلَنَا فَمَكَثَ عَنَّا لَيْلَةً لَمْ يَأْتِنَا حَتَّى طَالَ ذَلِكَ عَلَيْنَا بَعْدَ الْعِشَاءِ قَالَ قُلْنَا مَا أَمْكَثَكَ عَنَّا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏طَرَأَ عَنِّي حِزْبٌ مِنْ الْقُرْآنِ فَأَرَدْتُ أَنْ لَا أَخْرُجَ حَتَّى أَقْضِيَهُ فَسَأَلْنَا ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَصْبَحْنَا قَالَ قُلْنَا كَيْفَ ‏ ‏تُحَزِّبُونَ ‏ ‏الْقُرْآنَ قَالُوا ‏ ‏نُحَزِّبُهُ ‏ ‏سِتَّ سُوَرٍ وَخَمْسَ سُوَرٍ وَسَبْعَ سُوَرٍ وَتِسْعَ سُوَرٍ وَإِحْدَى عَشْرَةَ سُورَةً وَثَلَاثَ عَشْرَةَ سُورَةً وَحِزْبُ ‏ ‏الْمُفَصَّلِ ‏ ‏مِنْ ‏ ‏ق ‏ ‏حَتَّى تَخْتِمَ ‏","","",""],[18249,18249,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ التَّمَّارِّ ‏ ‏عَنِ ‏ ‏الْبَيَاضِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَى النَّاسِ وَهُمْ يُصَلُّونَ وَقَدْ عَلَتْ أَصْوَاتُهُمْ بِالْقِرَاءَةِ فَقَالَ ‏ ‏إِنَّ الْمُصَلِّي يُنَاجِي رَبَّهُ عَزَّ وَجَلَّ فَلْيَنْظُرْ مَا يُنَاجِيهِ وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقُرْآنِ ‏","","",""],[18250,18250,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏وُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَاقِدٍ اللَّيْثِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أَرْوَى ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ ثُمَّ آتِي الشَّجَرَةَ قَبْلَ غُرُوبِ الشَّمْسِ ‏","","",""],[18251,18251,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَرْبِ بْنُ أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏فَضَالَةَ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْلَمْتُ وَعَلَّمَنِي حَتَّى عَلَّمَنِي الصَّلَوَاتِ الْخَمْسَ لِمَوَاقِيتِهِنَّ قَالَ فَقُلْتُ لَهُ إِنَّ هَذِهِ لَسَاعَاتٌ أُشْغَلُ فِيهَا فَمُرْنِي بِجَوَامِعَ فَقَالَ لِي ‏ ‏إِنْ شُغِلْتَ فَلَا تُشْغَلْ عَنْ الْعَصْرَيْنِ قُلْتُ وَمَا الْعَصْرَانِ قَالَ صَلَاةُ الْغَدَاةِ وَصَلَاةُ الْعَصْرِ ‏","","",""],[18252,18252,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحَارِثِ ‏ ‏رَجُلٍ مِنْهُمْ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ضَمَّ يَتِيمًا بَيْنَ أَبَوَيْنِ مُسْلِمَيْنِ إِلَى طَعَامِهِ وَشَرَابِهِ حَتَّى يَسْتَغْنِيَ عَنْهُ وَجَبَتْ لَهُ الْجَنَّةُ ‏ ‏الْبَتَّةَ ‏ ‏وَمَنْ أَعْتَقَ امْرَأً مُسْلِمًا كَانَ فَكَاكَهُ مِنْ النَّارِ ‏ ‏يُجْزِي بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ مِنْ النَّارِ ‏","","",""],[18253,18253,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ ‏ ‏أَوْ ‏ ‏مَالِكِ بْنِ عَمْرٍو ‏ ‏كَذَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ضَمَّ يَتِيمًا بَيْنَ أَبَوَيْهِ فَلَهُ الْجَنَّةُ ‏ ‏الْبَتَّةَ ‏","","",""],[18254,18254,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أُبَيِّ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَدْرَكَ وَالِدَيْهِ أَوْ أَحَدَهُمَا ثُمَّ دَخَلَ النَّارَ مِنْ بَعْدِ ذَلِكَ فَأَبْعَدَهُ اللَّهُ وَأَسْحَقَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أُبَيِّ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏","","",""],[18255,18255,"","","‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏بَهْزٌ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ قَوْمِهِ يُقَالُ لَهُ ‏ ‏أُبَيُّ بْنُ مَالِكٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَدْرَكَ وَالِدَيْهِ أَوْ أَحَدَهُمَا فَدَخَلَ النَّارَ فَأَبْعَدَهُ اللَّهُ ‏","","",""],[18256,18256,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ عَمْرٍو الْقُشَيْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُسْلِمَةً فَهِيَ فِدَاؤُهُ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مَكَانَ كُلِّ عَظْمٍ مِنْ عِظَامِ مُحَرِّرِهِ بِعَظْمٍ مِنْ عِظَامِهِ ‏ ‏وَمَنْ أَدْرَكَ أَحَدَ وَالِدَيْهِ ثُمَّ لَمْ يُغْفَرْ لَهُ فَأَبْعَدَهُ اللَّهُ وَمَنْ ضَمَّ يَتِيمًا مِنْ بَيْنِ أَبَوَيْنِ مُسْلِمَيْنِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏إِلَى طَعَامِهِ وَشَرَابِهِ حَتَّى يُغْنِيَهُ اللَّهُ ‏ ‏وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[18257,18257,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ ‏ ‏عَنِ ‏ ‏الْخَشْخَاشِ الْعَنْبَرِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعِي ابْنٌ لِي قَالَ فَقَالَ ابْنُكَ هَذَا قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏لَا ‏ ‏يَجْنِي عَلَيْكَ وَلَا ‏ ‏تَجْنِي عَلَيْهِ ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏مَرَّةً ‏ ‏يُونُسُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُخْبِرٌ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ ‏","","",""],[18258,18258,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُهَاجِرٍ ‏ ‏يَعْنِي أَخَا ‏ ‏عَمْرِو بْنِ مُهَاجِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَقِيلُ بْنُ شَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ الْجُشَمِيِّ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِأَسْمَاءِ الْأَنْبِيَاءِ وَأَحَبُّ الْأَسْمَاءِ إِلَى اللَّهِ عَزَّ وَجَلَّ عَبْدُ اللَّهِ وَعَبْدُ الرَّحْمَنِ وَأَصْدَقُهَا حَارِثٌ وَهَمَّامٌ وَأَقْبَحُهَا حَرْبٌ وَمُرَّةُ ‏ ‏وَارْتَبِطُوا ‏ ‏الْخَيْلَ وَامْسَحُوا ‏ ‏بِنَوَاصِيهَا ‏ ‏وَأَعْجَازِهَا ‏ ‏أَوْ قَالَ ‏ ‏وَأَكْفَالِهَا ‏ ‏وَقَلِّدُوهَا ‏ ‏وَلَا ‏ ‏تُقَلِّدُوهَا ‏ ‏الْأَوْتَارَ ‏ ‏وَعَلَيْكُمْ بِكُلِّ ‏ ‏كُمَيْتٍ ‏ ‏أَغَرَّ ‏ ‏مُحَجَّلٍ ‏ ‏أَوْ أَشْقَرَ ‏ ‏أَغَرَّ ‏ ‏مُحَجَّلٍ ‏ ‏أَوْ ‏ ‏أَدْهَمَ ‏ ‏أَغَرَّ ‏ ‏مُحَجَّلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُهَاجَرِ ‏ ‏حَدَّثَنَا ‏ ‏عَقِيلُ بْنُ شَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ الْكَلَاعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَلَا أَدْرِي ‏ ‏بِالْكُمَيْتِ ‏ ‏بَدَأَ أَوْ ‏ ‏بِالْأَدْهَمِ ‏ ‏قَالَ وَسَأَلُوهُ لِمَ فَضَّلَ الْأَشْقَرَ قَالَ لِأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏فَكَانَ أَوَّلَ مَنْ جَاءَ بِالْفَتْحِ صَاحِبُ الْأَشْقَرِ ‏","","",""],[18259,18259,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏سُئِلَ عَنْ رَجُلٍ يُسَلِّمُ عَلَيْهِ وَهُوَ غَيْرُ مُتَوَضِّئٍ ‏ ‏فَقَالَ ثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏الْحُضَيْنِ أَبِي سَاسَانَ ‏ ‏عَنِ ‏ ‏الْمُهَاجِرِ بْنِ قُنْفُذٍ ‏ ‏أَنَّهُ سَلَّمَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَتَوَضَّأُ فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ فَرَدَّ عَلَيْهِ وَقَالَ إِنَّهُ ‏ ‏لَمْ يَمْنَعْنِي أَنْ أَرُدَّ عَلَيْكَ إِلَّا أَنِّي كَرِهْتُ أَنْ أَذْكُرَ اللَّهَ إِلَّا عَلَى طَهَارَةٍ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏الْحَسَنُ ‏ ‏مِنْ أَجْلِ هَذَا الْحَدِيثِ يَكْرَهُ أَنْ يَقْرَأَ ‏ ‏أَوْ يَذْكُرَ اللَّهَ عَزَّ وَجَلَّ ‏ ‏حَتَّى يَتَطَهَّرَ ‏","","",""],[18260,18260,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏فُلَانِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏النَّاسُ أَرْبَعَةٌ وَالْأَعْمَالُ سِتَّةٌ فَالنَّاسُ مُوَسَّعٌ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ وَمُوَسَّعٌ لَهُ فِي الدُّنْيَا ‏ ‏مَقْتُورٌ ‏ ‏عَلَيْهِ فِي الْآخِرَةِ ‏ ‏وَمَقْتُورٌ ‏ ‏عَلَيْهِ فِي الدُّنْيَا مُوَسَّعٌ عَلَيْهِ فِي الْآخِرَةِ وَشَقِيٌّ فِي الدُّنْيَا وَالْآخِرَةِ وَالْأَعْمَالُ ‏ ‏مُوجِبَتَانِ ‏ ‏وَمِثْلٌ بِمِثْلٍ وَعَشْرَةُ أَضْعَافٍ وَسَبْعُ مِائَةِ ضِعْفٍ ‏ ‏فَالْمُوجِبَتَانِ ‏ ‏مَنْ مَاتَ مُسْلِمًا مُؤْمِنًا لَا يُشْرِكُ بِاللَّهِ شَيْئًا فَوَجَبَتْ لَهُ الْجَنَّةُ وَمَنْ مَاتَ كَافِرًا وَجَبَتْ لَهُ النَّارُ وَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا فَعَلِمَ اللَّهُ أَنَّهُ قَدْ أَشْعَرَهَا قَلْبَهُ وَحَرَصَ عَلَيْهَا كُتِبَتْ لَهُ حَسَنَةً وَمَنْ هَمَّ بِسَيِّئَةٍ لَمْ تُكْتَبْ عَلَيْهِ وَمَنْ عَمِلَهَا كُتِبَتْ وَاحِدَةً وَلَمْ تُضَاعَفْ عَلَيْهِ وَمَنْ عَمِلَ حَسَنَةً كَانَتْ لَهُ بِعَشْرِ أَمْثَالِهَا وَمَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ بِسَبْعِ مِائَةِ ضِعْفٍ ‏","","",""],[18261,18261,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الرُّكَيْنُ بْنُ الرَّبِيعِ بْنِ عَمِيلَةَ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ كُتِبَتْ بِسَبْعِ مِائَةِ ضِعْفٍ ‏","","",""],[18262,18262,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏شَمْرِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ الْأَسَدِيِّ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ الرَّجُلُ أَنْتَ يَا ‏ ‏خُرَيْمُ ‏ ‏لَوْلَا ‏ ‏خُلَّتَانِ ‏ ‏قَالَ قُلْتُ وَمَا هُمَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِسْبَالُكَ ‏ ‏إِزَارَكَ ‏ ‏وَإِرْخَاؤُكَ ‏ ‏شَعْرَكَ ‏","","",""],[18263,18263,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ بْنِ عَمِيلَةَ الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ ‏ ‏اللَّهِ تُضَاعَفُ بِسَبْعِ مِائَةِ ضِعْفٍ ‏","","",""],[18264,18264,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خُرَيْمِ بْنِ فَاتِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَعْمَالُ سِتَّةٌ وَالنَّاسُ أَرْبَعَةٌ ‏ ‏فَمُوجِبَتَانِ ‏ ‏وَمِثْلٌ بِمِثْلٍ وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا وَالْحَسَنَةُ بِسَبْعِ مِائَةٍ فَأَمَّا ‏ ‏الْمُوجِبَتَانِ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ وَأَمَّا مِثْلٌ بِمِثْلٍ فَمَنْ هَمَّ بِحَسَنَةٍ حَتَّى يُشْعِرَهَا قَلْبَهُ وَيَعْلَمُ اللَّهُ عَزَّ وَجَلَّ ذَلِكَ مِنْهُ كُتِبَتْ لَهُ حَسَنَةً وَمَنْ عَمِلَ سَيِّئَةً كُتِبَتْ عَلَيْهِ سَيِّئَةً وَمَنْ عَمِلَ حَسَنَةً كُتِبَتْ لَهُ بِعَشْرِ أَمْثَالِهَا وَمَنْ أَنْفَقَ نَفَقَةً فِي سَبِيلِ اللَّهِ فَحَسَنَةٌ بِسَبْعِ مِائَةٍ وَالنَّاسُ أَرْبَعَةٌ مُوَسَّعٌ عَلَيْهِ فِي الدُّنْيَا ‏ ‏مَقْتُورٌ ‏ ‏عَلَيْهِ فِي الْآخِرَةِ وَمُوَسَّعٌ عَلَيْهِ فِي الْآخِرَةِ ‏ ‏مَقْتُورٌ ‏ ‏عَلَيْهِ فِي الدُّنْيَا وَمُوَسَّعٌ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ ‏ ‏وَمَقْتُورٌ ‏ ‏عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[18265,18265,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏أَبِي سَعِيدِ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ بِهِ جِنَازَةٌ فَقَامَ ‏","","",""],[18266,18266,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَدَّثَهُ ‏ ‏مُؤَذِّنُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمٍ مَطِيرٍ ‏ ‏صَلُّوا فِي ‏ ‏الرِّحَالِ ‏","","",""],[18267,18267,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أُخْبِرْتُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏حَدَّثَنِي ‏ ‏مُرَقِّعُ بْنُ صَيْفِيٍّ التَّمِيمِيُّ ‏ ‏شَهِدَ عَلَى ‏ ‏جَدِّهِ ‏ ‏رِيَاحِ بْنِ رُبَيِّعٍ الْحَنْظَلِيِّ الْكَاتِبِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ أَبِي الزِّنَادِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ ثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْمُرَقِّعُ بْنُ صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏رِيَاحِ بْنِ رُبَيِّعٍ ‏ ‏أَخِي ‏ ‏حَنْظَلَةَ الْكَاتِبِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُرَقِّعُ بْنُ صَيْفِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَدِّي ‏ ‏رِيَاحُ بْنُ رُبَيِّعٍ ‏ ‏أَخِي ‏ ‏حَنْظَلَةَ الْكَاتِبِ ‏ ‏أَنَّهُ خَرَجَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ عَلَى مُقَدِّمَتِهِ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَذَكَرَ رِيَاحًا وَأَصْلَهُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[18268,18268,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْنَا الْجَنَّةَ وَالنَّارَ حَتَّى كَانَا رَأْيَ عَيْنٍ فَقُمْتُ إِلَى أَهْلِي فَضَحِكْتُ وَلَعِبْتُ مَعَ أَهْلِي وَوَلَدِي فَذَكَرْتُ مَا كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْتُ فَلَقِيتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏نَافَقَ ‏ ‏حَنْظَلَةُ ‏ ‏قَالَ وَمَاذَاكَ ذَاكَ قُلْتُ كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْنَا الْجَنَّةَ وَالنَّارَ حَتَّى كَانَا رَأْيَ عَيْنٍ فَذَهَبْتُ إِلَى أَهْلِي فَضَحِكْتُ وَلَعِبْتُ مَعَ وَلَدِي وَأَهْلِي فَقَالَ إِنَّا لَنَفْعَلُ ذَاكَ قَالَ فَذَهَبْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ يَا ‏ ‏حَنْظَلَةُ ‏ ‏لَوْ كُنْتُمْ تَكُونُونَ فِي بُيُوتِكُمْ كَمَا تَكُونُونَ عِنْدِي لَصَافَحَتْكُمْ الْمَلَائِكَةُ وَأَنْتُمْ عَلَى فُرُشِكُمْ وَبِالطُّرُقِ يَا ‏ ‏حَنْظَلَةُ ‏ ‏سَاعَةً وَسَاعَةً ‏","","",""],[18269,18269,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ يَعْنِي الْقَطَّانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ الْأُسَيِّدِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا إِذَا كُنَّا عِنْدَكَ كُنَّا فَإِذَا فَارَقْنَاكَ كُنَّا عَلَى غَيْرِ ذَلِكَ فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْ كُنْتُمْ تَكُونُونَ عَلَى الْحَالِ الَّذِي تَكُونُونَ عَلَيْهَا عِنْدِي لَصَافَحَتْكُمْ الْمَلَائِكَةُ وَلَأَظَلَّتْكُمْ بِأَجْنِحَتِهَا ‏","","",""],[18270,18270,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَوَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏أَغَارَتْ ‏ ‏عَلَيْنَا خَيْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُهُ وَهُوَ يَتَغَدَّى فَقَالَ ادْنُ فَكُلْ قُلْتُ إِنِّي صَائِمٌ قَالَ اجْلِسْ أُحَدِّثْكَ عَنْ الصَّوْمِ ‏ ‏أَوْ الصِّيَامِ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَضَعَ عَنْ الْمُسَافِرِ ‏ ‏شَطْرَ ‏ ‏الصَّلَاةِ وَعَنْ الْمُسَافِرِ وَالْحَامِلِ وَالْمُرْضِعِ الصَّوْمَ ‏ ‏أَوْ الصِّيَامَ وَاللَّهِ لَقَدْ قَالَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِلَاهُمَا أَوْ أَحَدُهُمَا ‏ ‏فَيَا لَهْفَ نَفْسِي هَلَّا كُنْتُ طَعِمْتُ مِنْ طَعَامِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَوَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏وَلَيْسَ بِالْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَغَارَتْ ‏ ‏عَلَيْنَا خَيْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنَاه ‏ ‏شَيْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏قَالَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[18271,18271,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏وَيَزِيدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏عَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ هَذِهِ الْأُمَّةُ بِخَيْرٍ مَا عَظَّمُوا هَذِهِ الْحُرْمَةَ حَقَّ تَعْظِيمِهَا فَإِذَا تَرَكُوهَا وَضَيَّعُوهَا هَلَكُوا ‏ ‏وَقَالَ ‏ ‏فِي حَدِيثِ ‏ ‏يَزِيدَ بْنِ عَطَاءٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ سَابِطٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏الْعَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18272,18272,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَوْفَلِ بْنِ أَبِي عَقْرَبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّوْمِ فَقَالَ ‏ ‏صُمْ مِنْ الشَّهْرِ يَوْمًا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَقْوَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَقْوَى إِنِّي أَقْوَى صُمْ يَوْمَيْنِ مِنْ كُلِّ شَهْرٍ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ زِدْنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زِدْنِي زِدْنِي ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[18273,18273,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْجَعْدُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَهُ أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفًا ثُمَّ قَامَ فَمَضْمَضَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[18274,18274,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يَزْدَادَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَالَ أَحَدُكُمْ ‏ ‏فَلْيَنْتُرْ ‏ ‏ذَكَرَهُ ثَلَاثًا ‏ ‏قَالَ ‏ ‏زَمْعَةُ ‏ ‏مَرَّةً فَإِنَّ ذَلِكَ يُجْزِئُ عَنْهُ ‏","","",""],[18275,18275,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يَزْدَادَ بْنِ فَسَاءَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَالَ أَحَدُكُمْ ‏ ‏فَلْيَنْتُرْ ‏ ‏ذَكَرَهُ ثَلَاثَ مَرَّاتٍ ‏","","",""],[18276,18276,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي صَلَاةٍ لَيْسَتْ بِفَرِيضَةٍ فَمَرَّ بِذِكْرِ الْجَنَّةِ وَالنَّارِ فَقَالَ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ النَّارِ وَيْحٌ ‏ ‏أَوْ وَيْلٌ ‏ ‏لِأَهْلِ النَّارِ ‏","","",""],[18277,18277,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عِيسَى بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏يَحْبُو حَتَّى صَعِدَ عَلَى صَدْرِهِ فَبَالَ عَلَيْهِ قَالَ ‏ ‏فَابْتَدَرْنَاهُ ‏ ‏لِنَأْخُذَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنِي ابْنِي قَالَ ثُمَّ دَعَا بِمَاءٍ فَصَبَّهُ عَلَيْهِ ‏","","",""],[18278,18278,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي لَيْلَى ‏ ‏أَنَّهُ ‏ ‏كَانَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى بَطْنِهِ ‏ ‏الْحَسَنُ ‏ ‏أَوْ ‏ ‏الْحُسَيْنُ ‏ ‏شَكَّ ‏ ‏زُهَيْرٌ ‏ ‏قَالَ فَبَالَ حَتَّى رَأَيْتُ بَوْلَهُ عَلَى بَطْنِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسَارِيعَ ‏ ‏قَالَ ‏ ‏فَوَثَبْنَا ‏ ‏إِلَيْهِ قَالَ فَقَالَ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏دَعُوا ابْنِي ‏ ‏أَوْ لَا تُفْزِعُوا ابْنِي ‏ ‏قَالَ ثُمَّ دَعَا بِمَاءٍ فَصَبَّهُ عَلَيْهِ قَالَ فَأَخَذَ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ فَأَدْخَلَهَا فِي ‏ ‏فِيهِ قَالَ فَانْتَزَعَهَا رَسُولُ اللَّهِ مِنْ ‏ ‏فِيهِ ‏","","",""],[18279,18279,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتْحَ ‏ ‏خَيْبَرَ ‏ ‏فَلَمَّا انْهَزَمُوا وَقَعْنَا فِي ‏ ‏رِحَالِهِمْ ‏ ‏فَأَخَذَ النَّاسُ مَا وَجَدُوا مِنْ ‏ ‏خُرْثِيٍّ ‏ ‏فَلَمْ يَكُنْ أَسْرَعَ مِنْ أَنْ ‏ ‏فَارَتْ ‏ ‏الْقُدُورُ قَالَ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْقُدُورِ ‏ ‏فَأُكْفِئَتْ ‏ ‏وَقَسَمَ بَيْنَنَا فَجَعَلَ لِكُلِّ عَشَرَةٍ شَاةً ‏","","",""],[18280,18280,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى صَدْرِهِ ‏ ‏أَوْ بَطْنِهِ ‏ ‏الْحَسَنُ ‏ ‏أَوْ ‏ ‏الْحُسَيْنُ ‏ ‏قَالَ فَرَأَيْتُ بَوْلَهُ ‏ ‏أَسَارِيعَ ‏ ‏فَقُمْنَا إِلَيْهِ فَقَالَ ‏ ‏دَعُوا ابْنِي لَا تُفْزِعُوهُ حَتَّى يَقْضِيَ بَوْلَهُ ثُمَّ أَتْبَعَهُ الْمَاءَ ثُمَّ قَامَ فَدَخَلَ بَيْتَ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏وَدَخَلَ مَعَهُ الْغُلَامُ فَأَخَذَ تَمْرَةً فَجَعَلَهَا فِي ‏ ‏فِيهِ فَاسْتَخْرَجَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ إِنَّ ‏ ‏الصَّدَقَةَ ‏ ‏لَا تَحِلُّ لَنَا ‏","","",""],[18281,18281,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ هَاشِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏فِي الْمَسْجِدِ فَأُتِيَ بِرَجُلٍ ضَخْمٍ فَقَالَ يَا ‏ ‏أَبَا عِيسَى ‏ ‏قَالَ نَعَمْ قَالَ حَدِّثْنَا مَا سَمِعْتَ فِي الْفِرَاءِ فَقَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أُصَلِّي فِي الْفِرَاءِ قَالَ فَأَيْنَ ‏ ‏الدِّبَاغُ ‏ ‏فَلَمَّا وَلَّى قُلْتُ مَنْ هَذَا قَالَ هَذَا ‏ ‏سُوَيْدُ بْنُ غَفَلَةَ ‏","","",""],[18282,18282,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فِيمَا أَعْلَمُ شَكَّ ‏ ‏مُوسَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَكَفَ فِي ‏ ‏قُبَّةٍ ‏ ‏مِنْ خُوصٍ ‏","","",""],[18283,18283,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَأَبُو مَعْمَرٍ ‏ ‏وَمُحَمَّدُ بْنُ حَسَّانَ السَّمْتِيُّ ‏ ‏قَالُوا ثَنَا ‏ ‏عَلِيُّ بْنُ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَكَفَ فِي ‏ ‏قُبَّةٍ ‏ ‏مِنْ خُوصٍ ‏","","",""],[18284,18284,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّمْسَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ فَإِذَا ارْتَفَعَتْ فَارَقَهَا فَإِذَا كَانَتْ فِي وَسَطِ السَّمَاءِ قَارَنَهَا فَإِذَا ‏ ‏دَلَكَتْ ‏ ‏أَوْ قَالَ زَالَتْ ‏ ‏فَارَقَهَا فَإِذَا دَنَتْ لِلْغُرُوبِ قَارَنَهَا فَإِذَا غَرُبَتْ فَارَقَهَا فَلَا تُصَلُّوا هَذِهِ الثَّلَاثَ سَاعَاتٍ ‏","","",""],[18285,18285,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ أَبُو غَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَضْمَضَ وَاسْتَنْشَقَ خَرَّتْ خَطَايَاهُ مِنْ ‏ ‏فِيهِ وَأَنْفِهِ وَمَنْ غَسَلَ وَجْهَهُ خَرَجَتْ خَطَايَاهُ مِنْ ‏ ‏أَشْفَارِ ‏ ‏عَيْنَيْهِ وَمَنْ غَسَلَ يَدَيْهِ خَرَجَتْ مِنْ أَظْفَارِهِ ‏ ‏أَوْ مِنْ تَحْتِ أَظْفَارِهِ ‏ ‏وَمَنْ مَسَحَ رَأْسَهُ وَأُذُنَيْهِ خَرَجَتْ خَطَايَاهُ مِنْ رَأْسِهِ أَوْ شَعَرِ أُذُنَيْهِ وَمَنْ غَسَلَ رِجْلَيْهِ خَرَجَتْ خَطَايَاهُ مِنْ أَظْفَارِهِ ‏ ‏أَوْ تَحْتَ أَظْفَارِهِ ‏ ‏ثُمَّ كَانَتْ خُطَاهُ إِلَى الْمَسْجِدِ ‏ ‏نَافِلَةً ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏خَرَجَتْ خَطَايَاهُ مِنْ أَنْفِهِ وَفَمِهِ فَذَكَرَ مَعْنَاهُ ‏","","",""],[18286,18286,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏نَاقَةً ‏ ‏مُسِنَّةً ‏ ‏فَغَضِبَ وَقَالَ ‏ ‏مَا هَذِهِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي ارْتَجَعْتُهَا بِبَعِيرَيْنِ مِنْ ‏ ‏حَاشِيَةِ ‏ ‏الصَّدَقَةِ ‏ ‏فَسَكَتَ ‏","","",""],[18287,18287,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الصَّلْتُ يَعْنِي ابْنَ الْعَوَّامِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنْ تَزَالَ أُمَّتِي فِي ‏ ‏مَسَكَةٍ ‏ ‏مَا لَمْ يَعْمَلُوا بِثَلَاثٍ مَا لَمْ يُؤَخِّرُوا الْمَغْرِبَ بِانْتِظَارِ الْإِظْلَامِ ‏ ‏مُضَاهَاةَ ‏ ‏الْيَهُودِ ‏ ‏وَمَا لَمْ يُؤَخِّرُوا الْفَجْرَ ‏ ‏إِمْحَاقَ ‏ ‏النُّجُومِ ‏ ‏مُضَاهَاةَ ‏ ‏النَّصْرَانِيَّةِ وَمَا لَمْ ‏ ‏يَكِلُوا ‏ ‏الْجَنَائِزَ إِلَى أَهْلِهَا ‏","","",""],[18288,18288,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ فَمَضْمَضَ خَرَجَتْ الْخَطَايَا مِنْ أَنْفِهِ فَإِذَا غَسَلَ وَجْهَهُ خَرَجَتْ الْخَطَايَا مِنْ وَجْهِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ ‏ ‏أَشْفَارِ ‏ ‏عَيْنَيْهِ فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ خَطَايَاهُ مِنْ يَدَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ يَدَيْهِ فَإِذَا مَسَحَ رَأْسَهُ خَرَجَتْ الْخَطَايَا مِنْ رَأْسِهِ حَتَّى تَخْرُجَ مِنْ أُذُنَيْهِ وَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتْ الْخَطَايَا مِنْ رِجْلَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ رِجْلَيْهِ ثُمَّ كَانَ مَشْيُهُ إِلَى الْمَسْجِدِ وَصَلَاتُهُ ‏ ‏نَافِلَةً ‏ ‏لَهُ ‏","","",""],[18289,18289,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏قَيْسًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الصُّنَابِحِيَّ الْأَحْمَسِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَلَا ‏ ‏إِنِّي ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى ‏ ‏الْحَوْضِ ‏ ‏وَإِنِّي ‏ ‏مُكَاثِرٌ ‏ ‏بِكُمْ الْأُمَمَ فَلَا تَقْتَتِلُنَّ بَعْدِي ‏","","",""],[18290,18290,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَزُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا ثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ الصُّنَابِحِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّمْسَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ فَإِذَا طَلَعَتْ قَارَنَهَا فَإِذَا ارْتَفَعَتْ فَارَقَهَا وَيُقَارِنُهَا حِينَ ‏ ‏تَسْتَوِي فَإِذَا زَالَتْ فَارَقَهَا فَصَلُّوا غَيْرَ هَذِهِ السَّاعَاتِ الثَّلَاثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ ‏ ‏بِحَدِيثِ الشَّمْسِ ‏","","",""],[18291,18291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَخِي أَبِي رُهْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا رُهْمٍ الْغِفَارِيَّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ بَايَعُوا تَحْتَ الشَّجَرَةِ ‏ ‏يَقُولُ ‏ ‏غَزَوْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏فَلَمَّا ‏ ‏فَصَلَ ‏ ‏سَرَى ‏ ‏لَيْلَةً فَسِرْتُ قَرِيبًا مِنْهُ وَأُلْقِيَ عَلَيَّ النُّعَاسُ ‏ ‏فَطَفِقْتُ ‏ ‏أَسْتَيْقِظُ وَقَدْ ‏ ‏دَنَتْ ‏ ‏رَاحِلَتِي ‏ ‏مِنْ ‏ ‏رَاحِلَتِهِ ‏ ‏فَيُفْزِعُنِي ‏ ‏دُنُوُّهَا ‏ ‏خَشْيَةَ أَنْ أُصِيبَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏فَأُؤَخِّرُ ‏ ‏رَاحِلَتِي ‏ ‏حَتَّى غَلَبَتْنِي عَيْنِي فِي نِصْفِ اللَّيْلِ فَرَكِبَتْ ‏ ‏رَاحِلَتِي ‏ ‏رَاحِلَتَهُ ‏ ‏وَرِجْلُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْغَرْزِ ‏ ‏فَأَصَابَتْ رِجْلَهُ فَلَمْ أَسْتَيْقِظْ إِلَّا بِقَوْلِهِ ‏ ‏حَسِّ ‏ ‏فَرَفَعْتُ رَأْسِي فَقُلْتُ اسْتَغْفِرْ لِي يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏سَلْ فَقَالَ ‏ ‏فَطَفِقَ ‏ ‏يَسْأَلُنِي عَمَّنْ تَخَلَّفَ مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏فَأُخْبِرُهُ فَإِذَا هُوَ يَسْأَلُنِي مَا فَعَلَ ‏ ‏النَّفَرُ ‏ ‏الْحُمْرُ ‏ ‏الطُّوَالُ ‏ ‏الْقِطَاطُ ‏ ‏أَوْ قَالَ ‏ ‏الْقِصَارُ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏يَشُكُّ ‏ ‏الَّذِينَ لَهُمْ ‏ ‏نَعَمٌ ‏ ‏بِشَظِيَّةِ شَرْخٍ ‏ ‏قَالَ فَذَكَرْتُهُمْ فِي ‏ ‏بَنِي غِفَارٍ ‏ ‏فَلَمْ أَذْكُرْهُمْ حَتَّى ذَكَرْتُ ‏ ‏رَهْطًا ‏ ‏مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ مَا يَمْنَعُ أَحَدُ أُولَئِكَ حِينَ تَخَلَّفَ أَنْ يَحْمِلَ عَلَى بَعِيرٍ مِنْ إِبِلِهِ امْرَأً نَشِيطًا فِي سَبِيلِ اللَّهِ فَادْعُوا هَلْ أَنْ يَتَخَلَّفَ عَنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَالْأَنْصَارِ ‏ ‏وَأَسْلَمَ ‏ ‏وَغِفَارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَخِي أَبِي رُهْمٍ الْغِفَارِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا رُهْمٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ بَايَعُوا تَحْتَ الشَّجَرَةِ ‏ ‏يَقُولُ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏فَنِمْتُ لَيْلَةً ‏ ‏بِالْأَخْصَرِ ‏ ‏فَسِرْتُ قَرِيبًا مِنْهُ فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏مَعْمَرٍ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏فَطَفِقْتُ ‏ ‏أُؤَخِّرُ ‏ ‏رَاحِلَتِي ‏ ‏حَتَّى غَلَبَتْنِي عَيْنِي بَعْضَ اللَّيْلِ وَقَالَ مَا فَعَلَ ‏ ‏النَّفَرُ ‏ ‏السُّودُ ‏ ‏الْجِعَادُ ‏ ‏الْقِصَارُ ‏ ‏الَّذِينَ لَهُمْ ‏ ‏نَعَمٌ ‏ ‏بِشَظِيَّةِ شَرْخٍ ‏ ‏فَيَرَى أَنَّهُمْ مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏وَذَكَرَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ أُكَيْمَةَ اللَّيْثِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي أَبِي رُهْمٍ الْغِفَارِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا رُهْمٍ كُلْثُومَ بْنَ حُصَيْنٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ بَايَعُوا تَحْتَ الشَّجَرَةِ ‏ ‏يَقُولُ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ ‏ ‏فَطَفِقْتُ ‏ ‏أُؤَخِّرُ ‏ ‏رَاحِلَتِي ‏ ‏عَنْهُ حَتَّى غَلَبَتْنِي عَيْنِي وَقَالَ مَا فَعَلَ ‏ ‏النَّفَرُ ‏ ‏السُّودُ ‏ ‏الْجِعَادُ ‏ ‏الْقِصَارُ ‏ ‏قَالَ قُلْتُ وَاللَّهِ مَا أَعْرِفُ هَؤُلَاءِ مِنَّا حَتَّى قَالَ بَلَى الَّذِينَ لَهُمْ ‏ ‏نَعَمٌ ‏ ‏بِشَبَكَةِ شَرْخٍ ‏ ‏قَالَ فَتَذَكَّرْتُهُمْ فِي ‏ ‏بَنِي غِفَارٍ ‏ ‏فَلَمْ أَذْكُرْهُمْ حَتَّى ذَكَرْتُ أَنَّهُمْ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏أَسْلَمَ ‏ ‏كَانُوا حِلْفًا فِينَا فَقُلْتُ يَا رَسُولَ اللَّهِ أُولَئِكَ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏أَسْلَمَ ‏ ‏كَانُوا حُلَفَاءَنَا ‏","","",""],[18292,18292,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَاشِدُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ لُحَيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ قُرْطٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعْظَمُ الْأَيَّامِ عِنْدَ اللَّهِ ‏ ‏يَوْمُ النَّحْرِ ‏ ‏ثُمَّ ‏ ‏يَوْمُ النَّفْرِ ‏ ‏وَقُرِّبَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسُ ‏ ‏بَدَنَاتٍ ‏ ‏أَوْ سِتٌّ ‏ ‏يَنْحَرُهُنَّ ‏ ‏فَطَفِقْنَ ‏ ‏يَزْدَلِفْنَ ‏ ‏إِلَيْهِ أَيَّتُهُنَّ يَبْدَأُ بِهَا فَلَمَّا وَجَبَتْ ‏ ‏جُنُوبُهَا ‏ ‏قَالَ كَلِمَةً خَفِيَّةً لَمْ أَفْهَمْهَا فَسَأَلْتُ بَعْضَ مَنْ ‏ ‏يَلِينِي مَا قَالَ قَالُوا قَالَ مَنْ شَاءَ اقْتَطَعَ ‏","","",""],[18293,18293,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ زُرْعَةَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ عَبْدِ اللَّهِ الْأَزْدِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ قُرْطٍ الْأَزْدِيُّ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ ‏ ‏عَبْدُ اللَّهِ بْنُ قُرْطٍ ‏","","",""],[18294,18294,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏اللَّيْثِيِّينَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا لِي يَا رَسُولَ اللَّهِ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ قَالَ ‏ ‏الْجَنَّةُ قَالَ فَلَمَّا وَلَّى قَالَ إِلَّا الدَّيْنَ ‏ ‏سَارَّنِي ‏ ‏بِهِ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏آنِفًا ‏","","",""],[18295,18295,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏الْهِلَالِيِّينَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَاذَا لِي إِنْ قَاتَلْتُ فِي سَبِيلِ اللَّهِ حَتَّى أُقْتَلَ قَالَ ‏ ‏الْجَنَّةُ قَالَ فَلَمَّا ‏ ‏وَلَّى ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا الدَّيْنَ ‏ ‏سَارَّنِي ‏ ‏بِهِ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[18296,18296,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِسَكْرَانَ فَأَمَرَ مَنْ كَانَ مَعَهُ أَنْ يَضْرِبُوهُ بِمَا كَانَ فِي أَيْدِيهِمْ ‏","","",""],[18297,18297,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَزْهَرَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزَاةَ الْفَتْحِ وَأَنَا غُلَامٌ شَابٌّ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ ‏ ‏يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِشَارِبٍ فَأَمَرَ بِهِ فَضَرَبُوهُ بِمَا فِي أَيْدِيهِمْ فَمِنْهُمْ مَنْ ضَرَبَهُ بِنَعْلِهِ وَمِنْهُمْ مَنْ ضَرَبَهُ بِعَصًا وَمِنْهُمْ مَنْ ضَرَبَهُ بِسَوْطٍ ‏ ‏وَحَثَا ‏ ‏عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التُّرَابَ ‏","","",""],[18298,18298,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَزْهَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ بْنِ الْمُغِيرَةِ ‏ ‏خَرَجَ يَوْمَئِذٍ وَكَانَ عَلَى الْخَيْلِ خَيْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ أَزْهَرَ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَمَا هَزَمَ اللَّهُ الْكُفَّارَ وَرَجَعَ الْمُسْلِمُونَ إِلَى ‏ ‏رِحَالِهِمْ ‏ ‏يَمْشِي فِي الْمُسْلِمِينَ وَيَقُولُ ‏ ‏مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏قَالَ فَمَشَيْتُ ‏ ‏أَوْ فَسَعَيْتُ ‏ ‏بَيْنَ يَدَيْهِ وَأَنَا مُحْتَلِمٌ أَقُولُ مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏حَتَّى تَخَلَّلْنَا عَلَى ‏ ‏رَحْلِهِ ‏ ‏فَإِذَا ‏ ‏خَالِدٌ ‏ ‏مُسْتَنِدٌ إِلَى ‏ ‏مُؤْخِرَةِ ‏ ‏رَحْلِهِ ‏ ‏فَأَتَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ إِلَى جُرْحِهِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَحَسِبْتُ أَنَّهُ قَالَ ‏ ‏وَنَفَثَ ‏ ‏فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18299,18299,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَزْهَرَ ‏ ‏كَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّهُ حَضَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ كَانَ ‏ ‏يَحْثِي فِي وُجُوهِهِمْ التُّرَابَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَهَذَا يَتْلُو حَدِيثَ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ قَبِيصَةَ فِي شَارِبِ الْخَمْرِ ‏","","",""],[18300,18300,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا ثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ الْأَحْمَسِيِّ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى ‏ ‏الْحَوْضِ ‏ ‏وَإِنِّي مُكَاثِرٌ بِكُمْ الْأُمَمَ فَلَا تَقْتَتِلُنَّ بَعْدِي ‏","","",""],[18301,18301,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ أَبِي حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الصُّنَابِحِيَّ الْبَجَلِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى ‏ ‏الْحَوْضِ ‏ ‏وَمُكَاثِرٌ بِكُمْ الْأُمَمَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ النَّاسَ ‏ ‏فَلَا تَقْتَتِلُنَّ بَعْدِي ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ الْأَحْمَسِيِّ ‏ ‏مِثْلَهُ ‏","","",""],[18302,18302,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادِ بْنِ حَبِيبِ بْنِ الْمُهَلَّبِ بْنِ أَبِي صُفْرَةَ الْمُهَلَّبِيِّ أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏مُجَالِدِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي مُكَاثِرٌ بِكُمْ الْأُمَمَ فَلَا تَرْجِعُنَّ بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏الصُّنَابِحِ ‏","","",""],[18303,18303,"","","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏وَأَنَا شَاهِدٌ ‏ ‏سَمِعْتُ ‏ ‏مَعْمَرًا ‏ ‏يُحَدِّثُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏جُرِحَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُ عَنْ ‏ ‏رَحْلِهِ ‏ ‏قُلْتُ وَأَنَا غُلَامٌ مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدٍ ‏ ‏فَأَتَاهُ وَهُوَ مَجْرُوحٌ فَجَلَسَ عِنْدَهُ ‏","","",""],[18304,18304,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَزْهَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏وَهُوَ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ ‏ ‏يَسْأَلُ عَنْ ‏ ‏رَحْلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِسَكْرَانَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ عِنْدَهُ أَنْ يَضْرِبُوهُ بِمَا كَانَ فِي أَيْدِيهِمْ ‏ ‏وَحَثَا ‏ ‏عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التُّرَابَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَزْهَرَ الزُّهْرِيُّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏وَثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَذَكَرَهُ ‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏الصُّنَابِحِيُّ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَجِيلَةَ ‏ ‏مِنْ ‏ ‏أَحْمَسَ ‏","","",""],[18305,18305,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا تَسْتَعْمِلُنِي كَمَا اسْتَعْمَلْتَ فُلَانًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي غَدًا عَلَى ‏ ‏الْحَوْضِ ‏","","",""],[18306,18306,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏فَاطِمَةَ ابْنَةِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ ‏ ‏تَقُولُ ‏ ‏كَانَ ‏ ‏أُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏مِنْ أَفَاضِلِ النَّاسِ وَكَانَ يَقُولُ ‏ ‏لَوْ أَنِّي أَكُونُ كَمَا أَكُونُ عَلَى أَحْوَالٍ ثَلَاثٍ مِنْ أَحْوَالِي لَكُنْتُ حِينَ أَقْرَأُ الْقُرْآنَ وَحِينَ أَسْمَعُهُ يُقْرَأُ وَإِذَا سَمِعْتُ خُطْبَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا شَهِدْتُ جِنَازَةً وَمَا شَهِدْتُ جِنَازَةً قَطُّ فَحَدَّثْتُ نَفْسِي بِسِوَى مَا هُوَ مَفْعُولٌ بِهَا وَمَا هِيَ صَائِرَةٌ إِلَيْهِ ‏","","",""],[18307,18307,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏تَخَلَّى بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَا تَسْتَعْمِلُنِي كَمَا اسْتَعْمَلْتَ فُلَانًا قَالَ ‏ ‏إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى ‏ ‏الْحَوْضِ ‏","","",""],[18308,18308,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدِمْنَا مِنْ حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَتُلُقِّينَا ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏وَكَانَ غِلْمَانٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏تَلَقَّوْا أَهْلِيهِمْ فَلَقُوا ‏ ‏أُسَيْدَ بْنَ حُضَيْرٍ ‏ ‏فَنَعَوْا ‏ ‏لَهُ امْرَأَتَهُ ‏ ‏فَتَقَنَّعَ ‏ ‏وَجَعَلَ يَبْكِي قَالَتْ فَقُلْتُ لَهُ غَفَرَ اللَّهُ لَكَ أَنْتَ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكَ مِنْ السَّابِقَةِ وَالْقِدَمِ مَا لَكَ تَبْكِي عَلَى امْرَأَةٍ فَكَشَفَ عَنْ رَأْسِهِ وَقَالَ صَدَقْتِ لَعَمْرِي حَقِّي أَنْ لَا أَبْكِي عَلَى أَحَدٍ بَعْدَ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏وَقَدْ قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَالَ قَالَتْ قُلْتُ لَهُ مَا قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ اهْتَزَّ الْعَرْشُ لِوَفَاةِ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَتْ وَهُوَ يَسِيرُ بَيْنِي وَبَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18309,18309,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَأَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِنْ لُحُومِ الْإِبِلِ وَلَا تَوَضَّئُوا مِنْ لُحُومِ الْغَنَمِ وَصَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي مَبَارِكِ الْإِبِلِ ‏","","",""],[18310,18310,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ الْمَرْوَزِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ثِقَةً قَالَ وَكَانَ ‏ ‏الْحَكَمُ ‏ ‏يَأْخُذُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أُسَيْدِ بْنِ حُضَيْرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ عَنْ أَلْبَانِ الْإِبِلِ قَالَ ‏ ‏تَوَضَّئُوا مِنْ أَلْبَانِهَا وَسُئِلَ عَنْ أَلْبَانِ الْغَنَمِ فَقَالَ لَا تَوَضَّئُوا مِنْ أَلْبَانِهَا ‏","","",""],[18311,18311,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سُوَيْدِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏جَلَبْتُ أَنَا ‏ ‏وَمَخْرَمَةُ الْعَبْدِيُّ ‏ ‏ثِيَابًا مِنْ ‏ ‏هَجَرَ ‏ ‏قَالَ فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَاوَمَنَا ‏ ‏فِي ‏ ‏سَرَاوِيلَ ‏ ‏وَعِنْدَنَا وَزَّانُونَ يَزِنُونَ بِالْأَجْرِ فَقَالَ لِلْوَزَّانِ زِنْ وَأَرْجِحْ ‏","","",""],[18312,18312,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ أَبِي صَفْوَانَ بْنِ عَمِيرَةَ ‏ ‏قَالَ ‏ ‏بِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رِجْلَ ‏ ‏سَرَاوِيلَ ‏ ‏قَبْلَ الْهِجْرَةِ فَأَرْجَحَ لِي ‏","","",""],[18313,18313,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ ‏ ‏الدُّبَّاءُ ‏ ‏فَقُلْتُ مَا هَذَا قَالَ ‏ ‏نُكَثِّرُ بِهِ طَعَامَنَا ‏","","",""],[18314,18314,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ فَرَأَيْتُ عِنْدَهُ قَرْعًا فَقُلْتُ يَا رَسُولَ اللَّهِ مَا هَذَا قَالَ هَذَا ‏ ‏قَرْعٌ نُكَثِّرُ بِهِ طَعَامَنَا ‏","","",""],[18315,18315,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏مُدْرِكِ بْنِ عُمَارَةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ وَلَا يَزْنِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلَا ‏ ‏يَنْتَهِبُ ‏ ‏نُهْبَةً ‏ ‏ذَاتَ ‏ ‏شَرَفٍ ‏ ‏أَوْ سَرَفٍ ‏ ‏وَهُوَ مُؤْمِنٌ ‏","","",""],[18316,18316,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏وَعَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ فَالْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18317,18317,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ الْحَسَنِ الْمُزَنِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ حَسَنٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ذَلِكَ وَلَمْ يَقُلْ فِي الصَّلَاةِ ‏","","",""],[18318,18318,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنِي ‏ ‏الشَّيْبَانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ فَالْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18319,18319,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَعْلَى هُوَ ابْنُ عُبَيْدٍ ‏ ‏قَالَا ثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ وَهُوَ إِسْمَاعِيلُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْأَحْزَابِ فَقَالَ ‏ ‏اللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ ‏ ‏اهْزِمْ ‏ ‏الْأَحْزَابِ اهْزِمْهُمْ وَزَلْزِلْهُمْ ‏","","",""],[18320,18320,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏قَدِمْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏يَعْنِي فِي الْعُمْرَةِ ‏ ‏وَنَحْنُ نَسْتُرُهُ مِنْ الْمُشْرِكِينَ أَنْ يُؤْذُوهُ بِشَيْءٍ ‏","","",""],[18321,18321,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏لَوْ كَانَ بَعْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيٌّ مَا مَاتَ ابْنُهُ ‏ ‏إِبْرَاهِيمُ ‏","","",""],[18322,18322,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ أَبِي خَالِدٍ الدَّالَانِيِّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ السَّكْسَكِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي لَا أَسْتَطِيعُ أَخْذَ شَيْءٍ مِنْ الْقُرْآنِ فَعَلِّمْنِي مَا يُجْزِئُنِي قَالَ قُلْ ‏ ‏سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ يَا رَسُولَ اللَّهِ هَذَا لِلَّهِ عَزَّ وَجَلَّ فَمَا لِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي ثُمَّ أَدْبَرَ وَهُوَ مُمْسِكُ كَفَّيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا هَذَا فَقَدْ مَلَأَ يَدَيْهِ مِنْ الْخَيْرِ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏فَسَمِعْتُ ‏ ‏هَذَا الْحَدِيثَ مِنْ ‏ ‏إِبْرَاهِيمَ السَّكْسَكِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَثَبَّتَنِي فِيهِ غَيْرِي ‏","","",""],[18323,18323,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كَانَ الرَّجُلُ إِذَا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصَدَقَةِ ‏ ‏مَالِهِ ‏ ‏صَلَّى عَلَيْهِ ‏ ‏فَأَتَيْتُهُ ‏ ‏بِصَدَقَةِ ‏ ‏مَالِ أَبِي فَقَالَ ‏ ‏اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18324,18324,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي يَعْفُورٍ الْعَبْدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَ غَزَوَاتٍ فَكُنَّا نَأْكُلُ فِيهَا ‏ ‏الْجَرَادَ ‏","","",""],[18325,18325,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ هُوَ ابْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏بَجِيلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ ‏ ‏جَارِيَةٌ تَضْرِبُ بِالدُّفِّ ‏ ‏ثُمَّ ‏ ‏اسْتَأْذَنَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَدَخَلَ ثُمَّ اسْتَأْذَنَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَمْسَكَتْ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ حَيِيٌّ ‏","","",""],[18326,18326,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ هُوَ ابْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏شَيْخًا ‏ ‏بِالْمَدِينَةِ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏كَتَبَ إِلَى ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏إِذْ أَرَادَ أَنْ يَغْزُوَ ‏ ‏الْحَرُورِيَّةَ ‏ ‏فَقُلْتُ لِكَاتِبِهِ وَكَانَ لِي صَدِيقًا انْسَخْهُ لِي فَفَعَلَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا تَمَنَّوْا لِقَاءَ الْعَدُوِّ وَسَلُوا اللَّهَ عَزَّ وَجَلَّ الْعَافِيَةَ فَإِذَا لَقِيتُمُوهُمْ ‏ ‏فَاصْبِرُوا وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ قَالَ فَيَنْظُرُ إِذَا زَالَتْ الشَّمْسُ ‏ ‏نَهَدَ ‏ ‏إِلَى عَدُوِّهِ ثُمَّ قَالَ اللَّهُمَّ مُنْزِلَ الْكِتَابِ وَمُجْرِيَ السَّحَابِ وَهَازِمَ الْأَحْزَابِ اهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ ‏","","",""],[18327,18327,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ ‏ ‏بِصَدَقَةٍ ‏ ‏قَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَيْهِمْ وَإِنَّ أَبِي أَتَاهُ ‏ ‏بِصَدَقَتِهِ ‏ ‏فَقَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18328,18328,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيٍّ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏سَمِعْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏وَابْنَ أَبِي أَوْفَى ‏ ‏قَالَا ‏ ‏أَصَابُوا حُمُرًا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَنَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُكْفِئُوا الْقُدُورَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏عَدِيٍّ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏وَابْنِ أَبِي أوْفَى ‏","","",""],[18329,18329,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏بَجِيلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كَانَتْ ‏ ‏جَارِيَةٌ ‏ ‏تَضْرِبُ بِالدُّفِّ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏ثُمَّ جَاءَ ‏ ‏عُمَرُ ‏ ‏ثُمَّ جَاءَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَمْسَكَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ حَيِيٌّ ‏","","",""],[18330,18330,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَجْزَأَةَ بْنِ زَاهِرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَجْزَأَةَ بْنِ زَاهِرٍ ‏ ‏وَرَوْحٍ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَجْزَأَةَ بْنِ زَاهِرٍ ‏ ‏مَوْلًى ‏ ‏لِقُرَيْشٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ اللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ اللَّهُمَّ طَهِّرْنِي مِنْ الذُّنُوبِ وَنَقِّنِي مِنْهَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنْ الْوَسَخِ ‏","","",""],[18331,18331,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدًا أَبَا الْحَسَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو بِهَذَا الدُّعَاءِ ‏ ‏اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏أَبُو عِصْمَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ ‏","","",""],[18332,18332,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْفِئُوا الْقُدُورَ وَمَا فِيهَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏إِمَّا أَنْ يَكُونَ قَالَهُ ‏ ‏سُلَيْمَانُ ‏ ‏وَمَا فِيهَا أَوْ أَخْبَرَنِي مَنْ سَمِعَهُ مِنْ ‏ ‏ابْنِ أَبِي أَوْفَى ‏","","",""],[18333,18333,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْمُخْتَارِ ‏ ‏مَنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كُنَّا فِي سَفَرٍ فَلَمْ نَجِدْ الْمَاءَ قَالَ ثُمَّ هَجَمْنَا عَلَى الْمَاءِ بَعْدُ قَالَ فَجَعَلُوا يَسْقُونَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُلَّمَا أَتَوْهُ بِالشَّرَابِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاقِي الْقَوْمِ آخِرُهُمْ ثَلَاثَ مَرَّاتٍ حَتَّى شَرِبُوا كُلُّهُمْ ‏","","",""],[18334,18334,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي الْمُجَالِدِ ‏ ‏قَالَ ‏ ‏اخْتَلَفَ ‏ ‏عَبْدُ اللَّهِ بْنُ شَدَّادٍ ‏ ‏وَأَبُو بُرْدَةَ ‏ ‏فِي ‏ ‏السَّلَفِ ‏ ‏فَبَعَثَانِي إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏فَسَأَلْتُهُ فَقَالَ ‏ ‏كُنَّا ‏ ‏نُسْلِفُ ‏ ‏فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فِي ‏ ‏الْحِنْطَةِ ‏ ‏وَالشَّعِيرِ وَالزَّبِيبِ ‏ ‏أَوْ التَّمْرِ شَكَّ فِي التَّمْرِ وَالزَّبِيبِ ‏ ‏وَمَا هُوَ عِنْدَهُمْ ‏ ‏أَوْ مَا ‏ ‏نَرَاهُ عِنْدَهُمْ ‏ ‏ثُمَّ أَتَيْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبْزَى ‏ ‏فَقَالَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[18335,18335,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏أَخْبَرَنِي ‏ ‏طَلْحَةُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَوْصَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا قُلْتُ فَكَيْفَ أَمَرَ الْمُؤْمِنِينَ بِالْوَصِيَّةِ وَلَمْ يُوصِ قَالَ ‏ ‏أَوْصَى بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18336,18336,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي الْمُجَالِدِ ‏ ‏قَالَ ‏ ‏بَعَثَنِي أَهْلُ الْمَسْجِدِ إِلَى ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏أَسْأَلُهُ مَا صَنَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَعَامِ ‏ ‏خَيْبَرَ ‏ ‏فَأَتَيْتُهُ فَسَأَلْتُهُ عَنْ ذَلِكَ قَالَ وَقُلْتُ هَلْ خَمَّسَهُ قَالَ لَا كَانَ أَقَلَّ مِنْ ذَلِكَ قَالَ وَكَانَ أَحَدُنَا ‏ ‏إِذَا أَرَادَ مِنْهُ شَيْئًا أَخَذَ مِنْهُ حَاجَتَهُ ‏","","",""],[18337,18337,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏فِي عُمْرَتِهِ قَالَ لَا ‏","","",""],[18338,18338,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏الشَّيْبَانِيُّ ‏ ‏أَخْبَرَنِي قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ أَبِي أَوْفَى ‏ ‏رَجَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ يَهُودِيًّا وَيَهُودِيَّةً قَالَ قُلْتُ بَعْدَ نُزُولِ ‏ ‏النُّورِ ‏ ‏أَوْ قَبْلَهَا قَالَ لَا أَدْرِي ‏","","",""],[18339,18339,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الشَّيْبَانِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَكْلِ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ ‏","","",""],[18340,18340,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏الْمَعْنَى ‏ ‏قَالَا ثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَشَّرَ ‏ ‏خَدِيجَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏قَالَ نَعَمْ ‏ ‏بَشَّرَهَا بِبَيْتٍ فِي الْجَنَّةِ مِنْ ‏ ‏قَصَبٍ ‏ ‏لَا ‏ ‏صَخَبَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏ ‏قَالَ ‏ ‏يَعْلَى ‏ ‏وَقَالَ ‏ ‏مَرَّةً لَا ‏ ‏صَخَبَ ‏ ‏أَوْ لَا ‏ ‏لَغْوَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏","","",""],[18341,18341,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ اعْتَمَرَ ‏ ‏فَطَافَ وَطُفْنَا مَعَهُ وَصَلَّى وَصَلَّيْنَا مَعَهُ وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَكُنَّا نَسْتُرُهُ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏لَا يُصِيبُهُ أَحَدٌ بِشَيْءٍ ‏","","",""],[18342,18342,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْخَوَارِجُ ‏ ‏هُمْ كِلَابُ النَّارِ ‏","","",""],[18343,18343,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏اعْتَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَطُفْنَا مَعَهُ وَصَلَّى خَلْفَ ‏ ‏الْمَقَامِ ‏ ‏وَصَلَّيْنَا مَعَهُ ثُمَّ خَرَجَ فَطَافَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَنَحْنُ مَعَهُ نَسْتُرُهُ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏لَا يَرْمِيهِ أَحَدٌ ‏ ‏أَوْ يُصِيبُهُ أَحَدٌ ‏ ‏بِشَيْءٍ قَالَ فَدَعَا عَلَى الْأَحْزَابِ فَقَالَ ‏ ‏اللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ هَازِمَ الْأَحْزَابِ اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ قَالَ وَرَأَيْتُ بِيَدِهِ ضَرْبَةً عَلَى سَاعِدِهِ فَقُلْتُ مَا هَذِهِ قَالَ ضُرِبْتُهَا يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَقُلْتُ لَهُ أَشَهِدْتَ مَعَهُ ‏ ‏حُنَيْنًا ‏ ‏قَالَ نَعَمْ وَقَبْلَ ذَلِكَ ‏","","",""],[18344,18344,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ فَيَّاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ ‏","","",""],[18345,18345,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَاهُ قَوْمٌ ‏ ‏بِصَدَقَةٍ ‏ ‏قَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَيْهِمْ فَأَتَاهُ أَبِي ‏ ‏بِصَدَقَةٍ ‏ ‏فَقَالَ اللَّهُمَّ ‏ ‏صَلِّ ‏ ‏عَلَى آلِ ‏ ‏أَبِي أَوْفَى ‏","","",""],[18346,18346,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادِ بْنِ لَقِيطٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ وَنَحْنُ فِي الصَّفِّ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ فِي الصَّفِّ فَقَالَ اللَّهُ أَكْبَرُ كَبِيرًا وَسُبْحَانَ اللَّهِ ‏ ‏بُكْرَةً ‏ ‏وَأَصِيلًا ‏ ‏قَالَ فَرَفَعَ الْمُسْلِمُونَ رُءُوسَهُمْ وَاسْتَنْكَرُوا الرَّجُلَ وَقَالُوا مَنْ الَّذِي يَرْفَعُ صَوْتَهُ فَوْقَ صَوْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ هَذَا ‏ ‏الْعَالِي ‏ ‏الصَّوْتَ فَقِيلَ هُوَ ذَا يَا رَسُولَ اللَّهِ فَقَالَ وَاللَّهِ لَقَدْ ‏ ‏رَأَيْتُ كَلَامَكَ يَصْعَدُ فِي السَّمَاءِ حَتَّى فُتِحَ بَابٌ فَدَخَلَ فِيهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَاه ‏ ‏جَعْفَرُ بْنُ حُمَيْدٍ الْكُوفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادِ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏إِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏مِثْلَهُ ‏","","",""],[18347,18347,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏هَلْ أَوْصَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا قُلْتُ فَلِمَ كُتِبَ عَلَى الْمُسْلِمِينَ الْوَصِيَّةُ ‏ ‏أَوْ لِمَ أُمِرُوا بِالْوَصِيَّةِ ‏ ‏قَالَ أَوْصَى بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18348,18348,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حَسَنٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[18349,18349,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ السَّكْسَكِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي لَا أَسْتَطِيعُ أَنْ آخُذَ مِنْ الْقُرْآنِ شَيْئًا فَعَلِّمْنِي شَيْئًا يُجْزِئُنِي مِنْ الْقُرْآنِ قَالَ ‏ ‏سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ فَذَهَبَ ‏ ‏أَوْ قَامَ أَوْ نَحْوَ ذَا ‏ ‏قَالَ هَذَا لِلَّهِ عَزَّ وَجَلَّ فَمَا لِي قَالَ قُلْ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي ‏ ‏أَوْ ارْزُقْنِي وَاهْدِنِي وَعَافِنِي ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏وَرُبَّمَا قَالَ اسْتَفْهَمْتُ بَعْضَهُ مِنْ ‏ ‏أَبِي خَالِدٍ يَعْنِي الدَّالَانِيَّ ‏","","",""],[18350,18350,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حَسَنٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[18351,18351,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ الْهَجَرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏فَمَاتَتْ ابْنَةٌ لَهُ وَكَانَ يَتْبَعُ جِنَازَتَهَا عَلَى بَغْلَةٍ خَلْفَهَا فَجَعَلَ النِّسَاءُ يَبْكِينَ فَقَالَ لَا ‏ ‏تَرْثِينَ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمَرَاثِي ‏ ‏فَتُفِيضُ إِحْدَاكُنَّ مِنْ عَبْرَتِهَا مَا شَاءَتْ ثُمَّ كَبَّرَ عَلَيْهَا أَرْبَعًا ثُمَّ قَامَ بَعْدَ الرَّابِعَةِ قَدْرَ مَا بَيْنَ التَّكْبِيرَتَيْنِ يَدْعُو ثُمَّ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ فِي الْجِنَازَةِ هَكَذَا ‏","","",""],[18352,18352,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ ثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ أَنْ يَنْهَضَ إِلَى عَدُوِّهِ عِنْدَ زَوَالِ الشَّمْسِ ‏","","",""],[18353,18353,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ الْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18354,18354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ صَاحِبُ الْهَرَوِيِّ وَاسْمُهُ عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏بَشَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَدِيجَةَ ‏ ‏بِبَيْتٍ فِي الْجَنَّةِ مِنْ ‏ ‏قَصَبٍ ‏ ‏لَا ‏ ‏صَخَبَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏","","",""],[18355,18355,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏يَعْنِي ‏ ‏النَّبِيذَ ‏ ‏فِي ‏ ‏الْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏قُلْتُ فَالْأَبْيَضُ قَالَ لَا أَدْرِي ‏","","",""],[18356,18356,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَشَّرَ ‏ ‏خَدِيجَةَ ‏ ‏قَالَ نَعَمْ ‏ ‏بِبَيْتٍ مِنْ ‏ ‏قَصَبٍ ‏ ‏لَا ‏ ‏صَخَبَ ‏ ‏فِيهِ وَلَا ‏ ‏نَصَبَ ‏","","",""],[18357,18357,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقُومُ فِي الرَّكْعَةِ الْأُولَى مِنْ صَلَاةِ الظُّهْرِ حَتَّى لَا يُسْمَعَ وَقْعُ قَدَمٍ ‏","","",""],[18358,18358,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏وَعَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏أَنَّهُمْ ‏ ‏أَصَابُوا حُمُرًا فَطَبَخُوهَا قَالَ فَنَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْفِئُوا الْقُدُورَ ‏","","",""],[18359,18359,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ نَابِي ‏ ‏يَعْنِي ‏ ‏نَائِي ‏ ‏وَنَحْنُ فِي الصَّفِّ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ فِي الصَّفِّ ثُمَّ قَالَ اللَّهُ أَكْبَرُ كَبِيرًا وَسُبْحَانَ اللَّهِ ‏ ‏بُكْرَةً ‏ ‏وَأَصِيلًا ‏ ‏فَرَفَعَ الْمُسْلِمُونَ رُءُوسَهُمْ وَاسْتَنْكَرُوا الرَّجُلَ فَقَالُوا مَنْ الَّذِي يَرْفَعُ صَوْتَهُ فَوْقَ صَوْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا انْصَرَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ هَذَا ‏ ‏الْعَالِي ‏ ‏الصَّوْتَ قَالَ هُوَ ذَا يَا رَسُولَ اللَّهِ قَالَ وَاللَّهِ لَقَدْ ‏ ‏رَأَيْتُ كَلَامَكَ يَصْعَدُ فِي السَّمَاءِ حَتَّى فُتِحَ بَابٌ مِنْهَا فَدَخَلَ فِيهِ ‏","","",""],[18360,18360,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ جُمْهَانٍَ ‏ ‏قَالَ ‏ ‏كُنَّا نُقَاتِلُ ‏ ‏الْخَوَارِجَ ‏ ‏وَفِينَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى ‏ ‏وَقَدْ لَحِقَ لَهُ غُلَامٌ ‏ ‏بِالْخَوَارِجِ ‏ ‏وَهُمْ مِنْ ذَلِكَ الشَّطِّ وَنَحْنُ مِنْ ذَا الشَّطِّ فَنَادَيْنَاهُ ‏ ‏أَبَا فَيْرُوزَ ‏ ‏أَبَا فَيْرُوزَ ‏ ‏وَيْحَكَ ‏ ‏هَذَا مَوْلَاكَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى ‏ ‏قَالَ نِعْمَ الرَّجُلُ هُوَ لَوْ هَاجَرَ قَالَ مَا يَقُولُ عَدُوُّ اللَّهِ قَالَ قُلْنَا يَقُولُ نِعْمَ الرَّجُلُ لَوْ هَاجَرَ قَالَ فَقَالَ أَهِجْرَةٌ بَعْدَ هِجْرَتِي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طُوبَى ‏ ‏لِمَنْ قَتَلَهُمْ وَقَتَلُوهُ ‏","","",""],[18361,18361,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي يَعْفُورٍ ‏ ‏قَالَ ‏ ‏سَأَلَ شَرِيكِي وَأَنَا مَعَهُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏عَنْ الْجَرَادِ فَقَالَ لَا بَأْسَ بِهِ وَقَالَ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَ غَزَوَاتٍ فَكُنَّا نَأْكُلُهُ ‏","","",""],[18362,18362,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏ذَكَرْتُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏حَدِيثًا حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى ‏ ‏فِي لُحُومِ الْحُمُرِ فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏حَرَّمَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَتَّةَ ‏","","",""],[18363,18363,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَامَ يَخْطُبُ يَوْمَ تُوُفِّيَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏فَقَالَ عَلَيْكُمْ بِاتِّقَاءِ اللَّهِ عَزَّ وَجَلَّ وَالْوَقَارِ ‏ ‏وَالسَّكِينَةِ ‏ ‏حَتَّى يَأْتِيَكُمْ أَمِيرٌ فَإِنَّمَا ‏ ‏يَأْتِيكُمْ الْآنَ ثُمَّ قَالَ اشْفَعُوا لِأَمِيرِكُمْ فَإِنَّهُ كَانَ يُحِبُّ الْعَفْوَ وَقَالَ أَمَّا بَعْدُ فَإِنِّي أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أُبَايِعُكَ عَلَى الْإِسْلَامِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَشْتَرِطُ عَلَى النُّصْحِ لِكُلِّ مُسْلِمٍ فَبَايَعْتُهُ عَلَى هَذَا وَرَبِّ هَذَا الْمَسْجِدِ إِنِّي لَكُمْ لَنَاصِحٌ جَمِيعًا ثُمَّ اسْتَغْفَرَ وَنَزَلَ ‏","","",""],[18364,18364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ اشْتَرِطْ عَلَيَّ فَقَالَ ‏ ‏تَعْبُدُ اللَّهَ وَلَا تُشْرِكُ بِهِ شَيْئًا وَتُصَلِّي الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ وَتَنْصَحُ لِلْمُسْلِمِ وَتَبْرَأُ مِنْ الْكَافِرِ ‏","","",""],[18365,18365,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏طَارِقٍ التَّمِيمِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِنِسَاءٍ فَسَلَّمَ عَلَيْهِنَّ ‏","","",""],[18366,18366,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُبَيْلٍ ‏ ‏أَوْ ‏ ‏شِبْلٍ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏الْمُغِيرَةُ بْنُ شُبَيْلٍ يَعْنِي ابْنَ عَوْفٍ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا عَبْدٍ ‏ ‏أَبَقَ ‏ ‏فَقَدْ بَرِئَتْ مِنْهُ ‏ ‏الذِّمَّةُ ‏","","",""],[18367,18367,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً كَانَ لَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ ‏ ‏وِزْرُهَا ‏ ‏وَوِزْرُ ‏ ‏مَنْ عَمِلَ بِهَا مِنْ بَعْدِهِ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَوْنَ بْنَ أَبِي جَحْفَةَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَدْرِ النَّهَارِ فَذَكَرَهُ إِلَّا أَنَّهُ قَالَ فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ ثُمَّ دَخَلَ ثُمَّ خَرَجَ ‏ ‏يُصَلِّي وَقَالَ كَأَنَّهُ مُذْهَبَةٌ ‏","","",""],[18368,18368,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏أَنَّ رَجُلًا جَاءَ فَدَخَلَ فِي الْإِسْلَامِ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُهُ الْإِسْلَامَ وَهُوَ فِي مَسِيرِهِ فَدَخَلَ ‏ ‏خُفُّ ‏ ‏بَعِيرِهِ فِي ‏ ‏جُحْرِ ‏ ‏يَرْبُوعٍ ‏ ‏فَوَقَصَهُ ‏ ‏بَعِيرُهُ فَمَاتَ فَأَتَى عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَمِلَ قَلِيلًا وَأُجِرَ كَثِيرًا ‏ ‏قَالَهَا ‏ ‏حَمَّادٌ ‏ ‏ثَلَاثًا ‏ ‏اللَّحْدُ ‏ ‏لَنَا ‏ ‏وَالشَّقُّ ‏ ‏لِغَيْرِنَا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ الْبَجَلِيُّ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[18369,18369,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏قَالَ قَالَ ‏ ‏جَرِيرٌ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَظْرَةِ ‏ ‏الْفَجْأَةِ ‏ ‏فَأَمَرَنِي أَنْ أَصْرِفَ بَصَرِي ‏","","",""],[18370,18370,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أُبَايِعُكَ عَلَى الْإِسْلَامِ فَقَبَضَ يَدَهُ وَقَالَ ‏ ‏النُّصْحُ لِكُلِّ مُسْلِمٍ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ مَنْ لَمْ يَرْحَمْ النَّاسَ لَمْ يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18371,18371,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِلْمُسْلِمِ وَعَلَى فِرَاقِ الْمُشْرِكِ ‏","","",""],[18372,18372,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ وَعَلَى فِرَاقِ الْمُشْرِكِ ‏ ‏أَوْ كَلِمَةٍ مَعْنَاهَا ‏","","",""],[18373,18373,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا ظَبْيَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَمْ يَرْحَمْ النَّاسَ لَمْ يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18374,18374,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏أَنَّ ‏ ‏جَرِيرًا ‏ ‏قَالَ ‏ ‏يَا رَسُولَ اللَّهِ اشْتَرِطْ عَلَيَّ قَالَ ‏ ‏تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُصَلِّي الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ وَتَنْصَحُ الْمُسْلِمَ وَتَبْرَأُ مِنْ الْكَافِرِ ‏","","",""],[18375,18375,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَرْحَمُ مَنْ لَا يَرْحَمُ النَّاسَ ‏","","",""],[18376,18376,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُدْرِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏وَهُوَ جَدُّهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي حَجَّةِ الْوَدَاعِ يَا ‏ ‏جَرِيرُ ‏ ‏اسْتَنْصِتْ النَّاسَ ثُمَّ قَالَ فِي خُطْبَتِهِ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[18377,18377,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏قَالَ ‏ ‏بَالَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ لَهُ تَفْعَلُ هَذَا وَقَدْ بُلْتَ قَالَ نَعَمْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالَ ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏فَكَانَ يُعْجِبُهُمْ هَذَا الْحَدِيثُ لِأَنَّ إِسْلَامَ ‏ ‏جَرِيرٍ ‏ ‏كَانَ بَعْدَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏","","",""],[18378,18378,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18379,18379,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[18380,18380,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ ‏","","",""],[18381,18381,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَدْرِ النَّهَارِ قَالَ فَجَاءَهُ قَوْمٌ حُفَاةٌ عُرَاةٌ ‏ ‏مُجْتَابِي ‏ ‏النِّمَارِ ‏ ‏أَوْ الْعَبَاءِ ‏ ‏مُتَقَلِّدِي ‏ ‏السُّيُوفِ عَامَّتُهُمْ مِنْ ‏ ‏مُضَرَ ‏ ‏بَلْ كُلُّهُمْ مِنْ ‏ ‏مُضَرَ ‏ ‏فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِمَا رَأَى بِهِمْ مِنْ ‏ ‏الْفَاقَةِ ‏ ‏قَالَ فَدَخَلَ ثُمَّ خَرَجَ فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ وَأَقَامَ فَصَلَّى ثُمَّ خَطَبَ فَقَالَ ‏ { ‏يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ ‏ ‏إِلَى آخِرِ الْآيَةِ ‏ ‏إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا ‏} ‏وَقَرَأَ الْآيَةَ الَّتِي فِي ‏ ‏الْحَشْرِ ‏ { ‏وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ ‏} ‏تَصَدَّقَ رَجُلٌ مِنْ دِينَارِهِ مِنْ دِرْهَمِهِ مِنْ ثَوْبِهِ مِنْ ‏ ‏صَاعِ ‏ ‏بُرِّهِ ‏ ‏مِنْ ‏ ‏صَاعِ ‏ ‏تَمْرِهِ حَتَّى قَالَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ قَالَ فَجَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏بِصُرَّةٍ كَادَتْ كَفُّهُ تَعْجِزُ عَنْهَا بَلْ قَدْ عَجَزَتْ ثُمَّ تَتَابَعَ النَّاسُ حَتَّى رَأَيْتُ كَوْمَيْنِ مِنْ طَعَامٍ وَثِيَابٍ حَتَّى رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَهَلَّلُ وَجْهُهُ ‏ ‏يَعْنِي كَأَنَّهُ ‏ ‏مُذْهَبَةٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً حَسَنَةً فَلَهُ أَجْرُهَا وَأَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهُ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ ‏ ‏وِزْرُهَا ‏ ‏وَوِزْرُ ‏ ‏مَنْ عَمِلَ بِهَا بَعْدَهُ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَوْنَ بْنَ أَبِي جَحْفَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُنْذِرَ بْنَ جَرِيرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدْرَ النَّهَارِ فَذَكَرَهُ إِلَّا أَنَّهُ قَالَ وَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ ثُمَّ دَخَلَ ثُمَّ خَرَجَ فَصَلَّى وَقَالَ كَأَنَّهُ ‏ ‏مُذْهَبَةٌ ‏","","",""],[18382,18382,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَنَابٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا بَرَزْنَا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِذَا رَاكِبٌ يُوضِعُ نَحْوَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّ هَذَا الرَّاكِبَ إِيَّاكُمْ يُرِيدُ قَالَ فَانْتَهَى الرَّجُلُ إِلَيْنَا فَسَلَّمَ فَرَدَدْنَا عَلَيْهِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ أَقْبَلْتَ قَالَ مِنْ أَهْلِي وَوَلَدِي وَعَشِيرَتِي قَالَ فَأَيْنَ تُرِيدُ قَالَ أُرِيدُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَدْ أَصَبْتَهُ قَالَ يَا رَسُولَ اللَّهِ عَلِّمْنِي ‏ ‏مَا الْإِيمَانُ قَالَ تَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَتُقِيمُ الصَّلَاةَ ‏ ‏وَتُؤْتِي الزَّكَاةَ وَتَصُومُ رَمَضَانَ وَتَحُجُّ ‏ ‏الْبَيْتَ ‏ ‏قَالَ قَدْ أَقْرَرْتُ قَالَ ثُمَّ إِنَّ بَعِيرَهُ دَخَلَتْ يَدُهُ فِي شَبَكَةِ ‏ ‏جُرْذَانٍ ‏ ‏فَهَوَى بَعِيرُهُ وَهَوَى الرَّجُلُ فَوَقَعَ عَلَى ‏ ‏هَامَتِهِ ‏ ‏فَمَاتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيَّ بِالرَّجُلِ قَالَ ‏ ‏فَوَثَبَ ‏ ‏إِلَيْهِ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏وَحُذَيْفَةُ ‏ ‏فَأَقْعَدَاهُ فَقَالَا يَا رَسُولَ اللَّهِ قُبِضَ الرَّجُلُ قَالَ فَأَعْرَضَ عَنْهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا رَأَيْتُمَا إِعْرَاضِي عَنْ الرَّجُلَيْنِ فَإِنِّي رَأَيْتُ مَلَكَيْنِ يَدُسَّانِ فِي ‏ ‏فِيهِ مِنْ ثِمَارِ الْجَنَّةِ فَعَلِمْتُ أَنَّهُ مَاتَ جَائِعًا ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا وَاللَّهِ مِنْ الَّذِينَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ أُولَئِكَ لَهُمْ الْأَمْنُ وَهُمْ مُهْتَدُونَ ‏} ‏قَالَ ثُمَّ قَالَ دُونَكُمْ أَخَاكُمْ قَالَ فَاحْتَمَلْنَاهُ إِلَى الْمَاءِ فَغَسَّلْنَاهُ وَحَنَّطْنَاهُ وَكَفَّنَّاهُ وَحَمَلْنَاهُ إِلَى الْقَبْرِ قَالَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى جَلَسَ عَلَى شَفِيرِ الْقَبْرِ قَالَ فَقَالَ ‏ ‏أَلْحِدُوا ‏ ‏وَلَا ‏ ‏تَشُقُّوا ‏ ‏فَإِنَّ ‏ ‏اللَّحْدَ ‏ ‏لَنَا ‏ ‏وَالشَّقَّ ‏ ‏لِغَيْرِنَا ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ أَبِي جَعْفَرٍ الْفَرَّاءُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَبَيْنَا نَحْنُ نَسِيرُ إِذْ رَفَعَ لَنَا شَخْصٌ فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ وَقَعَتْ يَدُ ‏ ‏بَكْرِهِ ‏ ‏فِي بَعْضِ تِلْكَ الَّتِي تَحْفِرُ ‏ ‏الْجُرْذَانُ ‏ ‏وَقَالَ فِيهِ هَذَا مِمَّنْ عَمِلَ قَلِيلًا وَأُجِرَ كَثِيرًا ‏","","",""],[18383,18383,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَيَانُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ ‏","","",""],[18384,18384,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا حَجَبَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ أَسْلَمْتُ وَلَا رَآنِي إِلَّا تَبَسَّمَ فِي وَجْهِي ‏","","",""],[18385,18385,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏قَالَ وَقَالَ ‏ ‏جَرِيرٌ ‏ ‏لَمَّا ‏ ‏دَنَوْتُ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَخْتُ ‏ ‏رَاحِلَتِي ‏ ‏ثُمَّ حَلَلْتُ عَيْبَتِي ثُمَّ لَبِسْتُ ‏ ‏حُلَّتِي ‏ ‏ثُمَّ دَخَلْتُ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَرَمَانِي النَّاسُ ‏ ‏بِالْحَدَقِ ‏ ‏فَقُلْتُ لِجَلِيسِي يَا عَبْدَ اللَّهِ ذَكَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ذَكَرَكَ ‏ ‏آنِفًا ‏ ‏بِأَحْسَنِ ذِكْرٍ فَبَيْنَمَا هُوَ يَخْطُبُ إِذْ عَرَضَ ‏ ‏لَهُ فِي خُطْبَتِهِ وَقَالَ ‏ ‏يَدْخُلُ عَلَيْكُمْ مِنْ هَذَا الْبَابِ ‏ ‏أَوْ مِنْ هَذَا ‏ ‏الْفَجِّ ‏ ‏مِنْ خَيْرِ ذِي يَمَنٍ إِلَّا أَنَّ عَلَى وَجْهِهِ ‏ ‏مَسْحَةَ مَلَكٍ ‏ ‏قَالَ ‏ ‏جَرِيرٌ ‏ ‏فَحَمِدْتُ اللَّهَ عَزَّ وَجَلَّ عَلَى مَا أَبْلَانِي ‏ ‏و قَالَ ‏ ‏أَبُو قَطَنٍ ‏ ‏فَقُلْتُ لَهُ سَمِعْتَهُ مِنْهُ ‏ ‏أَوْ سَمِعْتَهُ مِنْ ‏ ‏الْمُغِيرَةِ بْنِ شِبْلٍ ‏ ‏قَالَ نَعَمْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ شُبَيْلِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏دَنَوْتُ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَخْتُ ‏ ‏رَاحِلَتِي ‏ ‏ثُمَّ حَلَلْتُ ‏ ‏عَيْبَتِي ‏ ‏ثُمَّ لَبِسْتُ ‏ ‏حُلَّتِي ‏ ‏قَالَ فَدَخَلْتُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَسَلَّمْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَمَانِي الْقَوْمُ ‏ ‏بِالْحَدَقِ ‏ ‏فَقُلْتُ لِجَلِيسِي هَلْ ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَمْرِي شَيْئًا ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18386,18386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّهُ ‏ ‏حِينَ بَايَعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ عَلَيْهِ أَنْ ‏ ‏لَا يُشْرِكَ بِاللَّهِ شَيْئًا وَيُقِيمَ الصَّلَاةَ وَيُؤْتِيَ الزَّكَاةَ وَيَنْصَحَ الْمُسْلِمَ وَيُفَارِقَ الْمُشْرِكَ ‏","","",""],[18387,18387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصُرَّةٍ ‏ ‏مِنْ ذَهَبٍ تَمْلَأُ مَا بَيْنَ أَصَابِعِهِ فَقَالَ هَذِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ثُمَّ قَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَعْطَوْا فَأَعْطَى ثُمَّ قَامَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَعْطَوْا فَأَعْطَى ثُمَّ قَامَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏فَأَعْطَوْا قَالَ فَأَشْرَقَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَأَيْتُ الْإِشْرَاقَ فِي ‏ ‏وَجْنَتَيْهِ ‏ ‏ثُمَّ قَالَ ‏ ‏مَنْ سَنَّ سُنَّةً صَالِحَةً فِي الْإِسْلَامِ فَعُمِلَ بِهَا بَعْدَهُ كَانَ لَهُ مِثْلُ أُجُورِهِمْ مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ أُجُورِهِمْ شَيْءٌ وَمَنْ سَنَّ فِي الْإِسْلَامِ سُنَّةً سَيِّئَةً فَعُمِلَ بِهَا بَعْدَهُ كَانَ عَلَيْهِ مِثْلُ ‏ ‏أَوْزَارِهِمْ ‏ ‏مِنْ غَيْرِ أَنْ يُنْتَقَصَ مِنْ ‏ ‏أَوْزَارِهِمْ ‏ ‏شَيْءٌ ‏","","",""],[18388,18388,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا وَهُوَ ابْنُ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ التَّيْمِيُّ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ ‏ ‏خَالِ ‏ ‏الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏مُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَأْوِي الضَّالَّةَ إِلَّا ضَالٌّ ‏","","",""],[18389,18389,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ إِلَى ‏ ‏ذِي الْخَلَصَةِ ‏ ‏فَكَسَرَهَا وَحَرَّقَهَا بِالنَّارِ ثُمَّ بَعَثَ رَجُلًا مِنْ ‏ ‏أَحْمَسَ ‏ ‏يُقَالُ لَهُ ‏ ‏بُشَيْرٌ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَشِّرُهُ ‏","","",""],[18390,18390,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ وَهُوَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ وَهُوَ ابْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخَاكُمْ ‏ ‏النَّجَاشِيَّ ‏ ‏قَدْ مَاتَ فَاسْتَغْفِرُوا لَهُ ‏","","",""],[18391,18391,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَصْدُرْ ‏ ‏الْمُصَدِّقُ وَهُوَ عَنْكُمْ رَاضٍ ‏","","",""],[18392,18392,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تُرِيحُنِي مِنْ ‏ ‏ذِي الْخَلَصَةِ ‏ ‏وَكَانَ بَيْتًا فِي ‏ ‏خَثْعَمَ ‏ ‏يُسَمَّى كَعْبَةَ الْيَمَانِيَةِ ‏ ‏فَنَفَرْتُ ‏ ‏إِلَيْهِ فِي سَبْعِينَ وَمِائَةِ فَارِسٍ مِنْ ‏ ‏أَحْمَسَ ‏ ‏قَالَ فَأَتَاهَا فَحَرَّقَهَا بِالنَّارِ وَبَعَثَ ‏ ‏جَرِيرٌ ‏ ‏بَشِيرًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَتَيْتُكَ حَتَّى تَرَكْتُهَا كَأَنَّهَا جَمَلٌ أَجْرَبُ فَبَرَّكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى خَيْلِ ‏ ‏أَحْمَسَ ‏ ‏وَرِجَالِهَا خَمْسَ مَرَّاتٍ ‏","","",""],[18393,18393,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏جَرِيرٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَا يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[18394,18394,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ أَبِي حَازِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْبَدْرِ فَقَالَ إِنَّكُمْ ‏ ‏سَتَرَوْنَ رَبَّكُمْ عَزَّ وَجَلَّ كَمَا تَرَوْنَ الْقَمَرَ لَا ‏ ‏تُضَامُونَ ‏ ‏فِي رُؤْيَتِهِ فَإِنْ اسْتَطَعْتُمْ أَنْ لَا ‏ ‏تُغْلَبُوا ‏ ‏عَلَى هَاتَيْنِ الصَّلَاتَيْنِ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ ثُمَّ تَلَا هَذِهِ الْآيَةَ فَ ‏ { ‏سَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ ‏} ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَدْرِي قَالَ فَإِنْ اسْتَطَعْتُمْ أَوْ لَمْ يَقُلْ ‏","","",""],[18395,18395,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏","","",""],[18396,18396,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ قَوْمٍ يَعْمَلُونَ بِالْمَعَاصِي وَفِيهِمْ رَجُلٌ أَعَزُّ مِنْهُمْ وَأَمْنَعُ لَا يُغَيِّرُونَ إِلَّا عَمَّهُمْ اللَّهُ عَزَّ وَجَلَّ بِعِقَابٍ ‏ ‏أَوْ قَالَ أَصَابَهُمْ الْعِقَابُ ‏","","",""],[18397,18397,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرًا ‏ ‏يَقُولُ ‏ ‏حِينَ مَاتَ ‏ ‏الْمُغِيرَةُ ‏ ‏وَاسْتَعْمَلَ قَرَابَتَهُ يَخْطُبُ فَقَامَ ‏ ‏جَرِيرٌ ‏ ‏فَقَالَ أُوصِيكُمْ بِتَقْوَى اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنْ تَسْمَعُوا وَتُطِيعُوا حَتَّى يَأْتِيَكُمْ أَمِيرٌ اسْتَغْفِرُوا ‏ ‏لِلْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏غَفَرَ اللَّهُ تَعَالَى لَهُ فَإِنَّهُ كَانَ يُحِبُّ ‏ ‏الْعَافِيَةَ ‏ ‏أَمَّا بَعْدُ فَإِنِّي أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُبَايِعُهُ بِيَدِي هَذِهِ عَلَى الْإِسْلَامِ ‏ ‏فَاشْتَرَطَ عَلَيَّ النُّصْحَ فَوَرَبِّ هَذَا الْمَسْجِدِ إِنِّي لَكُمْ لَنَاصِحٌ ‏","","",""],[18398,18398,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏فِي بَعْثٍ ‏ ‏بِأَرْمِينِيَّةَ ‏ ‏قَالَ فَأَصَابَتْهُمْ ‏ ‏مَخْمَصَةٌ ‏ ‏أَوْ مَجَاعَةٌ ‏ ‏قَالَ فَكَتَبَ ‏ ‏جَرِيرٌ ‏ ‏إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَمْ يَرْحَمْ النَّاسَ لَا يَرْحَمْهُ اللَّهُ عَزَّ وَجَلَّ قَالَ فَأَرْسَلَ إِلَيْهِ فَأَتَاهُ فَقَالَ ‏ ‏آنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ قَالَ ‏ ‏فَأَقْفَلَهُمْ ‏ ‏وَمَتَّعَهُمْ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏وَكَانَ أَبِي فِي ذَلِكَ الْجَيْشِ فَجَاءَ بِقَطِيفَةٍ مِمَّا مَتَّعَهُ ‏ ‏مُعَاوِيَةُ ‏","","",""],[18399,18399,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ثَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ فَقَالَ ‏ ‏فَلَقَّنِّي فَقَالَ فِيمَا اسْتَطَعْتَ وَالنُّصْحَ لِكُلِّ مُسْلِمٍ ‏","","",""],[18400,18400,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عُمَرٍو ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتِلُ ‏ ‏عُرْفَ فَرَسٍ بِأُصْبُعَيْهِ وَهُوَ يَقُولُ ‏ ‏الْخَيْلُ مَعْقُودٌ بِنَوَاصِيهَا الْخَيْرُ الْأَجْرُ وَالْمَغْنَمُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""]];
